function patient(){return withClinicalDefaults({name:$('#patient-name').value.trim(),weight:$('#patient-weight').value,years:$('#age-years').value,months:$('#age-months').value,days:$('#age-days').value,diagnosis:$('#patient-diagnosis').value.trim(),allergies:$('#patient-allergies').value.trim()||'não informado',comorbidities:$('#patient-comorbidities').value.trim()||'nenhuma',renal:$('#patient-renal')?.value||'',hepatic:$('#patient-hepatic')?.value||'',notes:$('#patient-notes').value.trim(),basis:'real',medications:$('#patient-medications').value.trim()||'nenhuma',coughType:$('#patient-cough').value,coughDays:$('#patient-cough-days').value,respiratoryAlarm:$('#patient-respiratory-alarm').value,pain:$('#patient-pain').checked,severe:$('#patient-severe').checked,vomiting:$('#patient-vomiting').checked,careSetting:$('#patient-setting').value});}
function currentGuidance(){const p=patient(),hasAge=[p.years,p.months,p.days].some(v=>v!=='');const months=hasAge?Number(p.years||0)*12+Number(p.months||0)+Number(p.days||0)/30.4375:NaN;const base=guidanceFor(p.diagnosis,months,{hospital:p.careSetting==='hospital'||state.rx.some(x=>x.route.startsWith('HOSPITALAR')),branch:state.notes.selectedBranch||''});return state.notes.contextKey===base.contextKey?{...base,...state.notes}:base;}
