function validatePatientAge(){const p=patient();if(!ageLabel())throw Error('Informe a idade do paciente.');for(const [v,label,max] of [[p.years,'anos',120],[p.months,'meses',11],[p.days,'dias',31]])if(v!==''){const n=number(v,{min:0,inclusive:true});if(!Number.isInteger(n)||n>max)throw Error(`Revise o campo ${label}.`);}}
