function safeURL(v){try{let u=new URL(v);return ['https:','http:'].includes(u.protocol)?u.href:null;}catch{return null;}}
function inlineMD(t){let out=esc(t);out=out.replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>').replace(/`([^`]+)`/g,'<code>$1</code>');out=out.replace(/\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)/g,(_,name,url)=>{const u=safeURL(url.replaceAll('&amp;','&'));return u?`<a href="${esc(u)}" target="_blank" rel="noopener noreferrer">${name}</a>`:name;});return out;}
function markdown(t){const lines=t.split('\n');let out='',table=false,ul=false;function close(){if(table){out+='</tbody></table></div>';table=false;}if(ul){out+='</ul>';ul=false;}}for(let i=0;i<lines.length;i++){const l=lines[i];if(/^\s*\|/.test(l)){if(/^\s*\|[ :|\-]+\|\s*$/.test(l))continue;if(!table){if(ul){out+='</ul>';ul=false;}out+='<div class="table-wrap"><table class="integrity-table"><tbody>';table=true;}out+='<tr>'+l.trim().replace(/^\||\|$/g,'').split('|').map(c=>`<td>${inlineMD(c.trim())}</td>`).join('')+'</tr>';continue;}if(table){out+='</tbody></table></div>';table=false;}const heading=/^(#{1,6})\s+(.+)$/.exec(l);if(heading){close();out+=`<h3 style="margin:22px 0 12px">${inlineMD(heading[2])}</h3>`;}else if(/^[-*]\s/.test(l)){if(!ul){out+='<ul>';ul=true;}out+=`<li>${inlineMD(l.slice(2))}</li>`;}else{if(ul){out+='</ul>';ul=false;}if(l.trim())out+=`<p>${inlineMD(l)}</p>`;}}close();return out;}
async function getJSON(path){if(dataCache.has(path))return dataCache.get(path);const compressed=path.startsWith('data/')&&path!=='data/manifest.json';const r=await fetch(compressed?path+'.gz':path);if(!r.ok)throw Error('Não foi possível carregar este conteúdo. Tente novamente.');let bytes=await r.arrayBuffer();if(new Uint8Array(bytes)[0]===31&&new Uint8Array(bytes)[1]===139){if(!globalThis.DecompressionStream)throw Error('Atualize o navegador para ler o acervo compactado.');bytes=await new Response(new Blob([bytes]).stream().pipeThrough(new DecompressionStream('gzip'))).arrayBuffer();}const d=JSON.parse(new TextDecoder().decode(bytes));dataCache.set(path,d);return d;}
function route(){state.route=location.hash.replace('#','')||'prescricao';if(state.route==='whatsapp'){location.hash='prescricao';state.route='prescricao';}if(!tabTitles[state.route])state.route='prescricao';const t=tabTitles[state.route];$('#eyebrow').textContent=t[0];$('#page-title').textContent=t[1];$('#page-subtitle').textContent=t[2];$('#current-title').textContent=t[3];$$('#nav a').forEach(a=>{a.classList.toggle('active',a.dataset.tab===state.route);a.setAttribute('aria-current',a.dataset.tab===state.route?'page':'false');});$('#sidebar').classList.remove('open');render();}
