function itemPrepared(item){if(!item.regimenId)throw Error('Item manual em quarentena: falta medicamento e apresentação documental vinculados.');if(regimens.find(r=>r.id===item.regimenId)?.requiredClinicalChecks?.length&&item.reviewedRevision!==state.patientRevision)throw Error('Os dados do paciente mudaram; confirme novamente as condições clínicas específicas deste esquema.');assertConfirmedHistory(patient());return prepareRegimen(item.regimenId,{...patient(),regimenChecks:item.regimenChecks||[]},item.regimenPresentation||0,item.regimenDuration||'');}
