function rxText({final=false}={}){const p=patient();let lines=[state.rx.some(x=>x.route.startsWith('HOSPITALAR'))?'PRESCRIÇÃO HOSPITALAR':state.rx.length?'RECEITUÁRIO MÉDICO':'ORIENTAÇÕES E PLANO DE CUIDADO',p.diagnosis?'Diagnóstico/indicação: '+p.diagnosis:null,p.coughType!=='none'?'Tosse: '+coughTypes[p.coughType]+' · '+(p.coughDays||'duração não informada')+' dias':null,p.weight?'Peso '+p.basis+': '+p.weight+' kg':null,ageLabel()?'Idade: '+ageLabel():null,'Data: '+new Date().toLocaleDateString('pt-BR',{timeZone:'America/Sao_Paulo'}),'Alergias: '+historyLabel(p,'allergies'),'Comorbidades: '+(p.comorbidities==='nenhuma'?'criança hígida':historyLabel(p,'comorbidities')),'Medicações de uso contínuo: '+(p.medications==='nenhuma'?'não usa':p.medications||'não informado')];let lastRoute='';for(const item of [...state.rx].sort((a,b)=>a.route.localeCompare(b.route))){if(item.route!==lastRoute){lines.push('\nUSO '+item.route);lastRoute=item.route;}try{let prepared=itemPrepared(item);lines.push(`\n— ${item.name} — ${item.presentation}`,preparedPrescriptionText(prepared),item.instructions||null);}catch{lines.push(`\n— ITEM BLOQUEADO — ${item.name}: NÃO EMITIR; reabra ou remova o item para registrar novamente as conferências.`);}}
const g=currentGuidance();if(g.clarification)lines.push('\nPLANO INDIVIDUALIZADO\n'+g.clarification);lines.push('\n'+guidanceText(g,{draft:!final}));lines.push('\nDr. Iago Vildete Almeida Chaves — CRM-MG 87901','Assinatura: __________________________________');return lines.filter(x=>x!==null&&x!==undefined).join('\n');}
