 $('#rx-med-search').addEventListener('input',e=>{const q=norm(e.target.value.trim());$('#rx-search-results').innerHTML=q?state.meds.filter(m=>norm(m.name).includes(q)).slice(0,8).map(m=>`<div class="list-row"><div class="grow"><h3>${esc(m.name)}</h3><p>${m.presentations.length?'Apresentações documentadas':'Monografia disponível'}</p></div><button class="button small soft" data-med="${m.id}">${regimensForMedication(m.id).length?'Ver opções':'Consultar'}</button></div>`).join(''):'';});
