function medCard(m){return `<button class="med-card" data-med="${m.id}"><div class="card-top"><span class="qicon">${icon('pill')}</span>${pill(m.number?'Ficha '+m.number:'Guia complementar')}</div><h3>${esc(m.name)}</h3><p>${esc(m.presentations[0]?.text||'Esquemas por indicação, população, via, monitorização e referências na monografia de origem.')}</p><div class="meta">${m.presentations.length?pill('Apresentações','teal'):''}${m.flags.contem_off_label?pill('Inclui off-label','amber'):''}${pill('Documental')}</div></button>`;}
function filteredMeds(){const q=norm(state.medQuery);return state.meds.filter(m=>(!q||norm(m.name+' '+m.presentations.map(p=>p.text).join(' ')).includes(q))&&(!state.medLetter||norm(m.name).startsWith(state.medLetter))&&(state.medFilter==='all'||state.medFilter==='presentations'&&m.presentations.length||state.medFilter==='offlabel'&&m.flags.contem_off_label));}
