function medicationPolicyNoteHTML(m){
 const note=medicationPolicyNoteFor(m);if(!note)return '';
 return `<section class="guidance-summary"><h3>Orientação da estratégia PNI 2026</h3><img class="medication-update-card" src="/ecards/nirsevimabe-2026-10-15.svg" alt="Nirsevimabe — atualização de apresentações e estratégia PNI em 15/10/2026"><p>Apresentações e dose validadas: ${esc(note.regulatoryAndSafetyDelta.presentations)}. ${esc(note.regulatoryAndSafetyDelta.dose)}</p><p class="small-text"><strong>Checagem dimensional:</strong> ${esc(note.regulatoryAndSafetyDelta.dimensionalCheck)}</p><p class="small-text"><strong>Segurança:</strong> ${esc(note.regulatoryAndSafetyDelta.safety)}</p><p class="small-text">Fontes A/B: <a href="${esc(safeURL(note.regulatoryAndSafetyDelta.regulatorySource.url)||'#')}" target="_blank" rel="noopener noreferrer">${esc(note.regulatoryAndSafetyDelta.regulatorySource.title)}</a> · <a href="${esc(safeURL(note.regulatoryAndSafetyDelta.protocolSource.url)||'#')}" target="_blank" rel="noopener noreferrer">${esc(note.regulatoryAndSafetyDelta.protocolSource.title)}</a></p><pre id="medication-policy-copy-ready" class="monograph" style="white-space:pre-wrap">${esc(note.copyReadyBlock)}</pre><div class="button-row"><button id="copy-medication-policy-note" class="button outline" type="button">${icon('copy')}Copiar orientação</button></div><p id="medication-policy-copy-feedback" class="small-text" aria-live="polite"></p><details class="guidance-sources"><summary>Fonte e limites da orientação</summary><p>${esc(note.source.entity)} · ${esc(note.source.title)}</p><p class="small-text">${esc(note.source.documentDateBasis)} Revisão documental da orientação: 15/10/2026.</p><p class="small-text">${esc(note.source.locator)}</p><p><a href="${esc(safeURL(note.source.url)||'#')}" target="_blank" rel="noopener noreferrer">Ler a nota técnica original</a></p><p>${esc(note.eligibilitySource.entity)} · ${esc(note.eligibilitySource.title)}</p><p class="small-text">${esc(note.eligibilitySource.locator)} Evidência B para idade cronológica inferior a 6 meses nos prematuros e validação clínica da indicação pela RIE; fonte de calendário/resgate preservada na nota técnica 89.</p><p><a href="${esc(safeURL(note.eligibilitySource.url)||'#')}" target="_blank" rel="noopener noreferrer">Ler o guia original de elegibilidade do PNI</a></p>${note.technicalLimits.map(text=>`<p>${esc(text)}</p>`).join('')}</details></section>`;
}
async function copyMedicationPolicyNote(note){
 const button=$('#copy-medication-policy-note'),feedback=$('#medication-policy-copy-feedback'),dialog=$('#detail-dialog'),generation=modalGeneration;
 if(!button||!feedback||!dialog.open||button.disabled)return;
 const current=()=>generation===modalGeneration&&dialog.open&&button.isConnected&&feedback.isConnected&&$('#copy-medication-policy-note')===button;
 button.disabled=true;feedback.textContent='';
 try{const text=assertFinalClinicalText(note.copyReadyBlock);if(!navigator.clipboard?.writeText)throw Error('clipboard unavailable');await navigator.clipboard.writeText(text);if(current())feedback.textContent='Orientação copiada.';}
 catch{if(current())feedback.textContent='Não foi possível copiar automaticamente. Selecione o bloco de orientação acima e copie manualmente.';}
 finally{if(current())button.disabled=false;}
}
function medicationCorrectionHTML(m){if(!m.correction)return '';const reviewed=(m.correction.reviewedAt||'2026-09-27').split('-').reverse().join('/');return `<div class="source-notice">${esc(m.correction.note)}</div><details class="guidance-sources"><summary>Fontes da correção · ${esc(reviewed)}</summary>${m.correction.sources.map((u,i)=>`<p><a href="${esc(safeURL(u)||'#')}" target="_blank" rel="noopener noreferrer">${i+1}. ${esc(new URL(u).hostname)} ↗</a></p>`).join('')}${m.originalPresentations?.length?`<h4>Lista original preservada</h4>${m.originalPresentations.map(p=>`<p>${esc(p.text)}</p>`).join('')}`:''}</details>`;}
function medicationReferencesHTML(id){const e=medicationEvidence[id];return e?.references.length?`<details class="guidance-sources"><summary>Referências da monografia (${e.references.length})</summary><p class="small-text">${esc(e.referenceProvenance)}</p>${e.references.map((u,i)=>`<p><a href="${esc(safeURL(u)||'#')}" target="_blank" rel="noopener noreferrer">${i+1}. ${esc(new URL(u).hostname)} ↗</a></p>`).join('')}</details>`:'';}
function keyName(n){return n.split(/[(/]/)[0].trim();}
function filteredTopics(){if(state.topicMode==='guidance')return filterDiagnosisCatalog(state.diagnosisCatalog,state.topicQuery);const q=norm(state.topicQuery),items=state.topicMode==='topics'?state.topics:state.diagnoses;return items.filter(t=>!q||norm((t.title||t.name)+' '+(t.aliases||[]).join(' ')).includes(q));}
function topicResults(){if(state.topicMode==='guidance'){guidanceResults();return;}const ts=filteredTopics(),size=30;state.topicPage=Math.min(state.topicPage,Math.max(0,Math.ceil(ts.length/size)-1));$('#topic-results').innerHTML=`<div class="result-summary"><span>${ts.length} ${state.topicMode==='topics'?'capítulos':'termos documentais'}</span></div><div class="panel">${ts.slice(state.topicPage*size,(state.topicPage+1)*size).map(t=>`<div class="list-row"><span class="list-index">${String(t.number).padStart(3,'0')}</span><div class="grow"><h3>${esc(t.title||t.name)}</h3><p>${state.topicMode==='topics'?'Capítulo PedWB · conteúdo documental integral':'Inventário de origem · termo não validado'}</p></div>${state.topicMode==='topics'?`<button class="button small soft" data-topic="${t.id}">Ler capítulo</button>`:`<button class="button small outline" data-source="${t.source}" data-source-page="${t.page}">Ver fonte</button>`}</div>`).join('')||'<div class="empty">Nenhum resultado para esta busca.</div>'}</div>${pager('topic',state.topicPage,ts.length,size)}`;}
function renderTopics(){setContent(`<div class="tabs"><button data-topic-mode="guidance" class="${state.topicMode==='guidance'?'active':''}">Orientações por diagnóstico</button><button data-topic-mode="topics" class="${state.topicMode==='topics'?'active':''}">Capítulos clínicos</button><button data-topic-mode="inventory" class="${state.topicMode==='inventory'?'active':''}">Inventário original</button></div>${state.topicMode==='guidance'?coverageHTML()+'<div id="pps-import-status">'+ppsImportStatusHTML()+'</div>':state.topicMode==='inventory'?'<div class="source-notice">A lista original contém variantes sem validade clínica, como qualificadores artificiais. Os termos são preservados para consulta documental; não geram diagnóstico ou tratamento automático.</div>':'<div class="info-strip">'+icon('books')+'<span>O PedWB é um compêndio documental complementar. A integração não representa revisão clínica de todos os capítulos nem acesso ao Whitebook externo.</span></div>'}<div class="toolbar"><div class="search-input">${icon('search')}<input id="topic-query" placeholder="Pesquisar tema ou diagnóstico…" value="${esc(state.topicQuery)}" aria-label="Pesquisar temas"></div></div><div id="topic-results"></div>`);$('#topic-query').oninput=e=>{state.topicQuery=e.target.value;state.topicPage=0;topicResults();};topicResults();}
function showTopic(id){const t=state.topics.find(t=>t.id===id);if(!t)return;openDialog(t.title,`<div class="source-notice">Capítulo documental preservado. Revisão clínica integral não declarada nesta integração; consulte as fontes e os limites do próprio capítulo.</div><div class="button-row" style="margin:0 0 20px"><button class="button outline" data-search-term="${esc(t.title)}">${icon('search')}Pesquisar nas outras fontes</button><button class="button outline" data-source="${t.source}">${icon('file')}Documento completo</button></div><div class="source-rich">${markdown(t.text)}</div>`,'PEDWB · CAPÍTULO '+t.number);}
function sourceCard(s){return `<article class="source-card"><div class="source-format">${esc(s.format)}</div><div class="source-info"><h3>${esc(s.title)}</h3><p>${esc(s.category)}</p><div class="source-facts"><span>${s.pages} ${s.format==='PDF'?'páginas':'seções'}</span><span>${fmt(s.bytes/1048576,1)} MB</span>${s.aliases.length>1?`<span>${s.aliases.length} referências preservadas</span>`:''}</div>${s.visualOnlyPages.length?pill('Inclui páginas visuais','amber'):''}<div class="button-row"><button class="button small soft" data-source="${s.id}">${icon('books')}Ler fonte</button><button class="button small outline" data-download="${s.id}">${icon('download')}Original</button></div></div></article>`;}
function sourceResults(){let fs=state.manifest.sources.filter(s=>(!state.sourceCategory||s.category===state.sourceCategory)&&norm(s.title+' '+s.name+' '+s.aliases.map(a=>a.name).join(' ')).includes(norm(state.sourceQuery))),size=18;state.sourcePage=Math.min(state.sourcePage,Math.max(0,Math.ceil(fs.length/size)-1));$('#source-results').innerHTML=`<div class="result-summary"><span>${fs.length} fontes únicas</span><span>Duplicatas idênticas agrupadas pelo conteúdo</span></div><div class="source-list">${fs.slice(state.sourcePage*size,(state.sourcePage+1)*size).map(sourceCard).join('')||'<div class="empty">Nenhuma fonte encontrada.</div>'}</div>${pager('source',state.sourcePage,fs.length,size)}`;}
function renderSources(){const cats=[...new Set(state.manifest.sources.map(s=>s.category))].sort();setContent(`<div class="toolbar"><div class="search-input">${icon('search')}<input id="source-query" value="${esc(state.sourceQuery)}" placeholder="Buscar pelo nome do arquivo…" aria-label="Pesquisar fontes"></div><select id="source-category" aria-label="Categoria da fonte"><option value="">Todas as categorias</option>${cats.map(c=>`<option>${esc(c)}</option>`).join('')}</select><button class="button outline" data-action="fulltext">${icon('search')}Buscar no conteúdo</button></div><div id="source-results"></div>`);$('#source-category').value=state.sourceCategory;$('#source-query').oninput=e=>{state.sourceQuery=e.target.value;state.sourcePage=0;sourceResults();};$('#source-category').onchange=e=>{state.sourceCategory=e.target.value;state.sourcePage=0;sourceResults();};sourceResults();}
function pdfURL(s,p){if(s.previewParts){let v=s.previewParts.find(x=>p>=x.start&&p<=x.end)||s.previewParts[0];return v.url+'#page='+(p-v.start+1);}return s.original+'#page='+p;}
async function showSource(id,page=1,mode='text'){
 const s=source(id);if(!s)return;openDialog(s.title,'<div class="loading">'+icon('books')+' Carregando documento…</div>','FONTE · '+s.format);const gen=modalGeneration;
 try{const d=await getJSON(`data/documents/${id}.json`);if(gen!==modalGeneration)return;page=Math.min(Math.max(1,Number(page)||1),Math.max(1,d.pages.length));const isPDF=s.format==='PDF'&&!s.damaged;if(isPDF&&s.visualOnlyPages.includes(page))mode='original';
 let content=mode==='original'&&isPDF?`<iframe class="source-viewer" src="${esc(pdfURL(s,page))}" title="Original de ${esc(s.title)}"></iframe>`:d.rich?.length?`<div class="source-rich">${d.rich[page-1]||esc(d.pages[page-1])}</div>`:['PNG','JPG','JPEG'].includes(s.format)?`<img src="${esc(s.original)}" alt="${esc(s.title)}" style="max-width:100%;height:auto">`:s.format==='MD'?`<div class="source-rich">${markdown(d.pages[page-1]||'')}</div>`:`<pre class="monograph">${esc(d.pages[page-1]||'Não há texto extraível nesta página. Consulte o arquivo original.')}</pre>`;
 $('#dialog-content').innerHTML=`${s.note?`<div class="source-notice">${esc(s.note)}</div>`:''}<div class="document-controls">${isPDF?`<button class="button small ${mode==='text'?'soft':'outline'}" data-source="${id}" data-source-page="${page}" data-mode="text">Texto extraído</button><button class="button small ${mode==='original'?'soft':'outline'}" data-source="${id}" data-source-page="${page}" data-mode="original">PDF original</button>`:''}<button class="button small outline" data-source="${id}" data-source-page="${page-1}" data-mode="${mode}" ${page<=1?'disabled':''}>Anterior</button><label style="flex-direction:row;align-items:center">Página/seção<input id="source-page-input" inputmode="numeric" value="${page}" data-source-id="${id}" data-mode="${mode}"></label><span class="small-text">de ${d.pages.length||1}</span><button class="button small outline" data-source="${id}" data-source-page="${page+1}" data-mode="${mode}" ${page>=d.pages.length?'disabled':''}>Próxima</button><button class="button small outline" data-download="${id}">${icon('download')}Original</button></div>${content}<details><summary>Origem, integridade e referências</summary><div class="source-facts">${s.aliases.map(a=>`<span>${esc(a.name)} · ${esc(a.origin)}</span>`).join('')}</div><p class="inline-notes">${esc(s.review)}</p><pre>SHA-256: ${s.sha256}</pre>${d.links.filter(l=>l.page===page).map(l=>`<p class="small-text"><a href="${esc(l.url)}" target="_blank" rel="noopener noreferrer">${esc(l.url)}</a></p>`).join('')}</details>`;
 $('#source-page-input').onchange=e=>{if(!/^\d+$/.test(e.target.value))return;showSource(id,Number(e.target.value),mode);};
 }catch(e){if(gen===modalGeneration)$('#dialog-content').innerHTML=`<div class="error">${esc(e.message)}</div>`;}
}
async function downloadSource(id){const s=source(id);if(!s)return;try{if(s.downloadParts){toast('Preparando o arquivo original completo…');const parts=[];for(const url of s.downloadParts){const r=await fetch(url);if(!r.ok)throw Error('Falha no download. Tente novamente.');parts.push(await r.arrayBuffer());}const blob=new Blob(parts,{type:'application/pdf'});if(crypto.subtle){const h=[...new Uint8Array(await crypto.subtle.digest('SHA-256',await blob.arrayBuffer()))].map(b=>b.toString(16).padStart(2,'0')).join('');if(h!==s.sha256)throw Error('A integridade do download não foi confirmada.');}saveBlob(blob,s.name);toast('Arquivo original recomposto e conferido.');}else{const a=document.createElement('a');a.href=s.original;a.download=s.name;document.body.append(a);a.click();a.remove();}}catch(e){toast(e.message);}}
function saveBlob(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);}
function startWorker(){if(searchWorker)return;searchWorker=new Worker('search-worker.js');searchWorker.onmessage=e=>{if(e.data.type==='results'){if(e.data.query!==state.searchQuery)return;state.searchData=e.data;if(state.route==='busca')searchResults();}else if(e.data.type==='error'){if(state.route==='busca')$('#search-results').innerHTML=`<div class="error">Busca parcial: ${esc(e.data.message)} ${e.data.loaded} de ${e.data.total} partes carregadas. Os originais continuam disponíveis.</div>`;}};searchWorker.postMessage({type:'init',urls:state.manifest.searchParts});}
function requestSearch(q){state.searchQuery=String(q).trim();state.searchData=null;startWorker();state.searchSeq++;searchWorker.postMessage({type:'search',query:state.searchQuery,seq:state.searchSeq});}
function searchTerm(q){closeDialog();requestSearch(q);$('#global-query').value=q;navigate('busca');}
function snippet(text,q){let escaped=esc(text);const terms=norm(q).split(/\s+/).filter(Boolean);if(terms.length===1){let n=norm(text),i=n.indexOf(terms[0]);if(i>=0)return esc(text.slice(0,i))+'<mark>'+esc(text.slice(i,i+terms[0].length))+'</mark>'+esc(text.slice(i+terms[0].length));}return escaped;}
function searchResults(){const r=state.searchData;if(!r){$('#search-results').innerHTML=state.searchQuery?'<div class="loading"><span class="spinner"></span>Preparando a pesquisa integral…</div>':'<div class="empty">Digite um medicamento, apresentação, diagnóstico ou termo clínico.</div>';return;}$('#search-results').innerHTML=`<div class="result-summary"><span>${r.count} trechos encontrados${r.count>200?' · exibindo os primeiros 200':''}</span><span>${r.ready?'Textos carregados':`Carregando acervo: ${r.loaded}/${r.total}`}</span></div>${!r.ready?`<div class="progress-track"><span style="width:${r.loaded/r.total*100}%"></span></div>`:''}<p class="inline-notes" style="margin-bottom:20px">Resultados referem-se ao texto extraído. Imagens, fórmulas incorporadas e páginas sem texto exigem leitura do original.</p>${r.hits.map(h=>`<article class="search-hit"><h3>${esc(sourceTitle(h.s))} ${pill('p. / seção '+h.p)}</h3><p>…${snippet(h.text,state.searchQuery)}…</p><button class="button small soft" data-source="${h.s}" data-source-page="${h.p}">Ler no contexto ${icon('arrow')}</button></article>`).join('')||'<div class="empty">Nenhum trecho encontrado. Tente menos termos ou outra grafia.</div>'}`;}
function renderSearch(){setContent(`<form id="local-search" class="toolbar"><div class="search-input">${icon('search')}<input id="search-query" value="${esc(state.searchQuery)}" placeholder="Pesquisar no texto das fontes…" aria-label="Termos para busca integral"></div><button class="button" type="submit">Pesquisar</button></form><div id="search-results"></div>`);$('#local-search').onsubmit=e=>{e.preventDefault();requestSearch($('#search-query').value);searchResults();};searchResults();}

function inputField(id,label,value='',extra=''){return `<label>${label}<input id="${id}" name="${id}" value="${esc(value)}" ${extra}></label>`;}
const units=(selected='mg')=>['mg','mcg','g','U','mU','mEq','mmol'].map(u=>`<option ${u===selected?'selected':''}>${u}</option>`).join('');
function doseFields(prefix='',initial={}){const f=initial;return `<div class="form-grid"><label>Base da dose<select id="${prefix}basis" name="${prefix}basis"><option value="kg-dose" ${f.basis==='kg-dose'?'selected':''}>Por kg por dose</option><option value="kg-day" ${f.basis==='kg-day'?'selected':''}>Por kg por dia</option><option value="fixed" ${f.basis==='fixed'?'selected':''}>Dose fixa por administração</option></select></label>${inputField(prefix+'dose','Dose de referência',f.dose||'','inputmode="decimal" placeholder="Definida para a indicação"')}<label>Unidade da dose<select id="${prefix}unit">${units(f.unit)}</select></label>${inputField(prefix+'amount','Quantidade na apresentação',f.amount||'','inputmode="decimal" placeholder="Ex.: 250"')}<label>Unidade da apresentação<select id="${prefix}concentrationUnit">${units(f.concentrationUnit||f.unit)}</select></label>${inputField(prefix+'volume','Volume correspondente · mL',f.volume||'','inputmode="decimal" placeholder="Ex.: 5"')}${inputField(prefix+'interval','Intervalo · horas',f.interval||'','inputmode="decimal" placeholder="Ex.: 8"')}${inputField(prefix+'step','Graduação da seringa · mL',f.step||'0.01','inputmode="decimal"')}<label class="check-label" style="align-self:center"><input type="checkbox" id="${prefix}single" ${f.single?'checked':''}>Dose única</label>${inputField(prefix+'maxDose','Teto por dose · mesma unidade',f.maxDose||'','inputmode="decimal" placeholder="Da referência"')}${inputField(prefix+'maxDay','Teto diário · mesma unidade',f.maxDay||'','inputmode="decimal" placeholder="Da referência"')}${inputField(prefix+'maxKgDay','Teto diário por kg · mesma unidade',f.maxKgDay||'','inputmode="decimal" placeholder="Da referência"')}${inputField(prefix+'dropFactor','Gotas/mL · apenas se confirmado',f.dropFactor||'','inputmode="decimal" placeholder="Opcional"')}<div class="span-2 inline-notes">As três opções de teto se complementam; o menor limite aplicável é usado. Campo vazio não significa ausência de limite. Conferir a mensurabilidade do volume arredondado.</div></div>`;}
function readDose(prefix=''){let f={};for(const k of ['basis','dose','unit','amount','concentrationUnit','volume','interval','step','maxDose','maxDay','maxKgDay','dropFactor'])f[k]=$('#'+prefix+k).value;f.single=$('#'+prefix+'single').checked;f.weight=patient().weight;return f;}
function doseResultHTML(r){return `<div class="results-grid"><div><div class="result-label">Volume por administração</div><div class="result-value">${fmt(r.practicalVolume,4)} <span class="result-unit">mL</span></div></div><div><div class="result-label">Dose administrada</div><div class="result-value">${fmt(r.administered,4)} <span class="result-unit">${esc(r.unit)}</span></div></div><div><div class="result-label">Exposição ${r.single?'nesta dose':'diária'}</div><div class="result-value">${fmt(r.perDay,4)} <span class="result-unit">${esc(r.unit)}</span></div></div></div><div class="formula">Concentração: ${fmt(r.concentration,6)} ${esc(r.unit)}/mL.<br>Dose antes do teto: ${fmt(r.raw,6)} ${esc(r.unit)}. ${r.cappedByLimit?`Teto aplicado: ${fmt(r.capped,6)} ${esc(r.unit)}.`:''}<br>Volume exato: ${fmt(r.capped,6)} ÷ ${fmt(r.concentration,6)} = ${fmt(r.exactVolume,6)} mL.<br>Arredondamento: ${fmt(r.practicalVolume,4)} mL · variação ${fmt(r.delta,3)}%.<br>Reversa: ${fmt(r.practicalVolume,4)} mL × ${fmt(r.concentration,6)} ${esc(r.unit)}/mL = ${fmt(r.reverseDose,4)} ${esc(r.unit)} = ${fmt(r.perKgDose,4)} ${esc(r.unit)}/kg/dose.<br>Exposição: ${fmt(r.perKgDay,4)} ${esc(r.unit)}/kg/${r.single?'dose':'dia'}.${r.dropFactor?`<br>Equivalência matemática: ${fmt(r.exactDrops,3)} gotas, com fator informado ${fmt(r.dropFactor)} gotas/mL. Não administrar fração de gota; selecionar um esquema mensurável.`:''}</div><div class="review-check pass">${icon('check')}Cálculo dimensional e reverso conferidos</div>`;}
function configureMedication(medId=null,editId=null,preset=null){const selected=state.rx.find(x=>x.id===editId);if(selected?.regimenId&&!preset){regimenDialog(selected.regimenId,editId,selected);return;}const existing=state.rx.find(x=>x.id===editId),old=existing?{...existing}:preset,m=state.meds.find(x=>x.id===medId)||state.meds.find(x=>x.id===old?.medId);if(old?.regimenId){try{const refreshed=prepareRegimen(old.regimenId,{...patient(),regimenChecks:old.regimenChecks||[]},old.regimenPresentation||0,old.regimenDuration||'');old.form=refreshed.form;old.duration=refreshed.duration;}catch(e){toast(e.message);return;}}const f=old?.form||{};openDialog(existing?'Editar medicamento':'Configurar medicamento',`<form id="med-form" novalidate>${old?.regimenId?regimenNotice(old.regimenId):''}<div class="form-section"><div class="form-grid two">${inputField('item-name','Princípio ativo / componente da dose',old?.name||m?.name||'','required')}${inputField('item-indication','Indicação individual',old?.indication||patient().diagnosis||'','required')}<label class="span-2">Apresentação e concentração por extenso<input id="item-presentation" value="${esc(old?.presentation||'')}" placeholder="Ex.: suspensão oral 250 mg/5 mL" required></label><label>Via / destino<select id="item-route">${['ORAL','NASAL','INALATÓRIO','TÓPICO','OCULAR','OTOLÓGICO','RETAL','HOSPITALAR — EV','HOSPITALAR — IM','HOSPITALAR — SC','HOSPITALAR — IO'].map(r=>`<option ${old?.route===r?'selected':''}>${r}</option>`).join('')}</select></label>${inputField('item-duration','Duração ou critério de suspensão',old?.duration||'','placeholder="Ex.: por 10 dias" required')}<label class="span-2">Fonte do esquema e dos limites<input id="item-source" value="${esc(old?.reference||(m?sourceTitle(m.source)+' — p. '+m.page:''))}" placeholder="Bula/diretriz, indicação, página e versão" required></label></div></div><div class="form-section"><h3>Dose e apresentação</h3><p class="inline-notes" style="margin:-6px 0 15px">Peso atual: <strong>${esc(patient().weight||'não informado')} kg</strong>. ${old?.regimenId?'Esquema preenchido pela indicação, idade e peso. Confira apresentação, mensurabilidade e aplicabilidade.':'Cálculo manual suspenso sem vínculo documental canônico. Consulte os esquemas estruturados na ficha e no plano terapêutico.'}</p>${doseFields('item-',f)}<label class="check-label" style="margin-top:17px"><input id="item-no-limit" type="checkbox" ${old?.noLimit?'checked':''}>A referência informada não estabelece um teto numérico aplicável a este esquema.</label></div>${m?`<details><summary>Consultar monografia e apresentações durante o preenchimento</summary>${m.presentations.map(p=>`<div class="info-strip">${esc(p.text)}</div>`).join('')}<pre class="monograph">${esc(m.text)}</pre></details>`:''}<label>Instruções específicas para administração<textarea id="item-instructions" placeholder="Somente orientações pertinentes e conferidas">${esc(old?.instructions||'')}</textarea></label><div id="item-result" aria-live="polite"></div><div class="check-group"><label class="check-label"><input type="checkbox" id="check-clinical">Conferi indicação, idade, alergias, contraindicações, interações, duração, máximos e ajustes pertinentes ao paciente.</label><label class="check-label"><input type="checkbox" id="check-pharmacy">Conferi princípio ativo, componente-base, apresentação, concentração, via e fonte. Para alta vigilância, realizar dupla checagem humana.</label></div><div id="item-error"></div><div class="button-row"><button type="button" class="button outline" id="item-calculate">${icon('calculator')}Conferir cálculo</button><button type="submit" class="button">${icon('plus')}${existing?'Salvar item':'Adicionar ao receituário'}</button></div><p class="inline-notes">Declarações do prescritor são registradas com o item; não equivalem a revisão clínica automatizada ou assinatura digital.</p></form>`,'PRESCRIÇÃO · ESQUEMA INDIVIDUAL');
 if(old?.regimenId){for(const key of ['basis','dose','unit','amount','concentrationUnit','volume','interval','maxDose','maxDay','maxKgDay','single','dropFactor']){const el=$('#item-'+key);el.disabled=true;}for(const key of ['name','presentation','duration'])$('#item-'+key).readOnly=true;$('#item-route').disabled=true;if(f.dropFactor)$('#item-step').disabled=true;}let calculated=null;const calculate=()=>{try{if(!old?.regimenId)throw Error('Cálculo manual de volume suspenso: selecione um esquema com medicamento e apresentação documental vinculados.');assertConfirmedHistory(patient());const input=readDose('item-');calculated=calculateDose(input);$('#item-result').innerHTML='<div class="results-box">'+doseResultHTML(calculated)+'</div>';$('#item-error').innerHTML='';return calculated;}catch(e){calculated=null;$('#item-result').innerHTML='';$('#item-error').innerHTML='<div class="error">'+esc(e.message)+'</div>';return null;}};
 $('#item-calculate').onclick=calculate;
 $('#med-form').oninput=e=>{if(e.target.id==='check-clinical'||e.target.id==='check-pharmacy')return;$('#check-clinical').checked=false;$('#check-pharmacy').checked=false;calculated=null;$('#item-result').innerHTML='';};
 $('#med-form').onsubmit=e=>{e.preventDefault();try{validatePatientAge();const name=$('#item-name').value.trim(),indication=$('#item-indication').value.trim(),presentation=$('#item-presentation').value.trim(),duration=$('#item-duration').value.trim(),reference=$('#item-source').value.trim(),route=$('#item-route').value;if(!name||!indication||!presentation||!duration||!reference)throw Error('Preencha medicamento, indicação, apresentação, duração e fonte do esquema.');if(route.startsWith('HOSPITALAR')&&!$('#item-instructions').value.trim())throw Error('Registre preparo, diluente, volume final, tempo/velocidade, via e condições de administração hospitalar.');const form=readDose('item-');if(!form.maxDose&&!form.maxDay&&!form.maxKgDay&&!$('#item-no-limit').checked)throw Error('Informe os máximos da referência ou registre que ela não estabelece teto aplicável.');if(!$('#check-clinical').checked||!$('#check-pharmacy').checked)throw Error('Registre as conferências clínica e farmacêutica.');const r=calculate();if(!r)return;if(state.rx.some(x=>x.id!==editId&&norm(x.name)===norm(name)&&x.route===route))throw Error('Este medicamento já está na mesma via. Edite o item existente para evitar duplicidade.');const item={id:editId||crypto.randomUUID(),regimenId:old?.regimenId||null,regimenPresentation:old?.regimenPresentation||0,regimenDuration:old?.regimenDuration||'',group:old?.group||'adjunct',rationale:old?.rationale||'',offLabel:old?.offLabel||'',medId:m?.id||null,name,indication,presentation,duration,reference,route,instructions:$('#item-instructions').value,noLimit:$('#item-no-limit').checked,form,reviewedRevision:state.patientRevision,reviewedAt:new Date().toISOString()};validatePrescriptionItems([...state.rx.filter(x=>x.id!==editId),item]);if(existing)state.rx=state.rx.map(x=>x.id===editId?item:x);else state.rx.push(item);state.notesReviewedRevision=-1;closeDialog();navigate('prescricao');toast('Item adicionado com cálculo e conferências registrados.');}catch(err){$('#item-error').innerHTML='<div class="error">'+esc(err.message)+'</div>';}};
}
function guidanceDecisionHTML(g,{select=false}={}){
 const d=g.decisionSupport;if(!d)return '';
 const branches=d.branches||[];
 return `<section class="decision-support span-2"><h3>Critérios para este atendimento</h3><p>${esc(d.summary||'')}</p>${g.evidenceSummary?`<p class="inline-notes">${esc(g.evidenceSummary)}</p>`:''}${d.requirements?.length?`<details><summary>Dados que modificam a conduta</summary><ul>${d.requirements.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></details>`:''}${select&&branches.length?`<label>Subtipo ou contexto confirmado ${d.branchRequired?'· selecione para carregar as orientações':''}<select id="guidance-branch" ${d.branchRequired?'required':''}><option value="">Selecione conforme a avaliação</option>${branches.map(b=>`<option value="${esc(b.id)}" ${g.selectedBranch===b.id?'selected':''}>${esc(b.label)}</option>`).join('')}</select></label>`:''}${g.selectionCriteria?`<p class="source-notice"><strong>Critério da opção selecionada:</strong> ${esc(g.selectionCriteria)}</p>`:''}${branches.length?`<details><summary>Quando utilizar cada opção</summary>${branches.map(b=>`<div class="guidance-branch"><strong>${esc(b.label)}</strong><p>${esc(b.when)}</p>${!select?`<p>${esc(b.overrides?.diagnosis||'')}</p>`:''}</div>`).join('')}</details>`:''}</section>`;
}
function notesDialog(draft=null){
 const g=draft||currentGuidance();
 openDialog('Orientações do receituário',`<p class="source-notice">${g.matched?'Os seis blocos foram preenchidos automaticamente para este diagnóstico. Ajustes são opcionais; as fontes ficam disponíveis para conferência.':'Selecione um diagnóstico do catálogo para carregar todos os cuidados, a evolução e o retorno automaticamente.'}</p>${g.scopeNotice?`<p class="source-notice">${esc(g.scopeNotice)}</p>`:''}<form id="notes-form" class="form-grid two guidance-fields">${guidanceDecisionHTML(g,{select:true})}${guidanceFields.map(([k,l])=>`<label class="span-2">${l}<textarea id="note-${k}" required maxlength="3000">${esc(g[k]||'')}</textarea></label>`).join('')}${g.status==='needs-review'?`<label class="span-2">Esclarecimento do diagnóstico e plano individual · obrigatório<textarea id="note-clarification" required minlength="20" maxlength="1200">${esc(g.clarification||'')}</textarea></label>`:''}<label class="span-2">Medidas não farmacológicas adicionais · opcional<textarea id="note-nonpharm" maxlength="3000">${esc(g.nonpharm||'')}</textarea></label><details class="span-2 guidance-sources"><summary>Fontes e revisão científica</summary>${g.reviewNotes?`<p class="small-text">${esc(g.reviewNotes)}</p>`:''}${guidanceSources(g).map(url=>`<p class="small-text"><a href="${esc(url)}" target="_blank" rel="noopener noreferrer">Fonte das orientações ↗ ${esc(new URL(url).hostname)}</a></p>`).join('')}<p class="inline-notes">Consulta documental: ${esc((g.revisedAt||'2026-09-26').split('-').reverse().join('/'))}. O preenchimento não estabelece critérios de alta.</p></details><label class="check-label span-2"><input id="notes-reviewed" type="checkbox" required>Conferi os cuidados, a evolução esperada, os sinais de alarme e os critérios de retorno para este paciente.</label><div class="span-2"><button class="button" type="submit">Salvar e conferir orientações</button></div></form>`,'RECEITUÁRIO COMPLETO');
 if($('#guidance-branch'))$('#guidance-branch').onchange=e=>{
  const modified=guidanceFields.some(([k])=>$('#note-'+k).value!==(g[k]||''))||$('#note-nonpharm').value!==(g.nonpharm||'');
  if(modified&&!window.confirm('Carregar as orientações da nova opção? As alterações ainda não salvas neste formulário serão substituídas.')){e.target.value=g.selectedBranch||'';return;}
  const p=patient(),hasAge=[p.years,p.months,p.days].some(v=>v!==''),months=hasAge?Number(p.years||0)*12+Number(p.months||0)+Number(p.days||0)/30.4375:NaN;
  const next=guidanceFor(p.diagnosis,months,{hospital:p.careSetting==='hospital'||state.rx.some(x=>x.route.startsWith('HOSPITALAR')),branch:e.target.value});state.notesReviewedRevision=-1;notesDialog(next);
 };
 $('#notes-form').onsubmit=e=>{e.preventDefault();const next={...g};for(const [k] of [...guidanceFields,['nonpharm']])next[k]=$('#note-'+k).value;try{if(g.status==='needs-review'){next.clarification=$('#note-clarification').value;if(next.clarification.trim().length<20)throw Error('Esclareça o diagnóstico, subtipo ou plano individual antes de emitir.');}if(!$('#notes-reviewed').checked)throw Error('Confirme a revisão das orientações.');validateGuidance(next);if((state.notes.selectedBranch||'')!==(next.selectedBranch||''))state.patientRevision++;state.notes=next;state.notesReviewedRevision=state.patientRevision;closeDialog();render();}catch(err){toast(err.message);}};
}

function ensureRx(){assertConfirmedHistory(patient());if(!patient().diagnosis)throw Error('Informe o diagnóstico ou indicação do atendimento.');validatePatientAge();if(state.rx.some(x=>x.reviewedRevision!==state.patientRevision))throw Error('Os dados do paciente mudaram. Abra os itens para recalcular e registrar novamente as conferências.');validatePrescriptionItems(state.rx);for(const x of state.rx)itemResult(x);validateGuidance(currentGuidance());if(!currentGuidance().autoFilled&&state.notesReviewedRevision!==state.patientRevision)throw Error('Selecione um diagnóstico do catálogo ou revise as orientações deste atendimento.');assertFinalClinicalText(rxText({final:true}));}
function canExportRx(){try{ensureRx();return true;}catch{return false;}}
async function exportRx(print=false){try{ensureRx();const text=rxText({final:true});if(print){$('#print-area').textContent=text;window.print();}else{await navigator.clipboard.writeText(text);toast('Bloco final copiado. Revise e assine antes do uso.');}}catch(e){toast(e.message);}}
function preparePrintArea(){const area=$('#print-area');if(!area)return;try{ensureRx();area.textContent=rxText({final:true});}catch{area.textContent='';}}
window.addEventListener('beforeprint',preparePrintArea);
function renderCalculators(){setContent(`<div class="tabs">${[['dose','Dose e volume'],['infusion','Infusão contínua'],['intermittent','Infusão intermitente'],['concentration','Concentração'],['bsa','Superfície corporal']].map(([k,v])=>`<button data-calc="${k}" class="${state.calcMode===k?'active':''}">${v}</button>`).join('')}</div><div id="calculator"></div>`);renderCalculator();}
function renderCalculator(){const mode=state.calcMode;if(!['concentration','bsa'].includes(mode)){$('#calculator').innerHTML='<div class="source-notice danger"><strong>Operação manual suspensa</strong><p>O contrato destes campos não confirma por documento a identidade do medicamento, a apresentação e a concentração. Parâmetros declarados não habilitam mL, preparo ou infusão. Consulte o esquema estruturado e a apresentação pertinentes no atendimento.</p></div>';return;}
 const configs={concentration:['Concentração final','Quantidade · mg','Volume final · mL','mg/mL'],bsa:['Superfície corporal — Mosteller','Peso · kg','Estatura · cm','m²']};const [title,a,b,unit]=configs[mode];$('#calculator').innerHTML=`<section class="panel"><div class="panel-head"><h2>${title}</h2></div><form id="simple-calc" class="panel-body"><div class="form-grid two">${inputField('simple-a',a,mode==='bsa'?patient().weight:'','inputmode="decimal"')}${inputField('simple-b',b,'','inputmode="decimal"')}</div><div class="button-row"><button type="submit" class="button">Calcular</button></div><div id="simple-result"></div><p class="inline-notes">${mode==='bsa'?'Fórmula de Mosteller: √(peso × altura ÷ 3600). O cálculo não escolhe nem valida dose em mg/m².':'mg/mL = quantidade em mg ÷ volume FINAL em mL. Não equivale à concentração original da ampola.'}</p></form></section>`;$('#simple-calc').onsubmit=e=>{e.preventDefault();try{const fn={concentration,bsa}[mode],r=fn($('#simple-a').value,$('#simple-b').value);$('#simple-result').innerHTML=`<div class="results-box"><div class="result-value">${fmt(r,4)} <span class="result-unit">${unit}</span></div></div>`;}catch(err){$('#simple-result').innerHTML='<div class="error">'+esc(err.message)+'</div>';}};$('#simple-calc').oninput=()=>$('#simple-result').innerHTML='';
}
function renderReview(){const s=state.manifest.stats,visual=state.manifest.sources.filter(x=>x.visualOnlyPages.length||x.embeddedImages);setContent(`${coverageHTML()}${stats()}<div class="audit-cards"><div class="audit-card">${pill('Concluído','teal')}<h3 style="margin-top:14px">Preservação documental</h3><p>${s.aliases} arquivos de origem foram integrados em ${s.sources} fontes únicas. Cópias idênticas compartilham conteúdo; nomes e procedências permanecem registrados.</p></div><div class="audit-card">${pill('Operacional','teal')}<h3 style="margin-top:14px">Cálculos e receituário</h3><p>Os esquemas estruturados preenchem dose, apresentação, limites, duração e instruções. O sistema calcula volumes ou unidades, diferencia etapas do tratamento, confere a reversa e exige recálculo quando os dados mudam.</p></div><div class="audit-card">${pill('Revisão parcial','amber')}<h3 style="margin-top:14px">Conteúdo clínico</h3><p>${new Set(regimens.map(r=>r.medicationId)).size} medicamentos têm ao menos um esquema estruturado, somando ${regimens.length} opções. As ${state.meds.length} entradas foram preservadas. Referências extraídas das monografias não representam revisão completa dos demais esquemas. Há checagens específicas de duplicidade e incompatibilidade, sem cobertura universal de interações.</p></div></div><section class="panel"><div class="panel-head"><h2>Mapa de integração</h2></div><div class="table-wrap"><table class="integrity-table"><thead><tr><th>Componente</th><th>Conteúdo disponível</th><th>Aplicação</th></tr></thead><tbody><tr><td>Catálogo-base</td><td>${s.baseMedications} monografias com texto integral</td><td>Consulta dos esquemas por indicação e fonte</td></tr><tr><td>Farmacoterapia</td><td>${s.guideRecords} entradas com apresentações documentadas</td><td>Complemento cruzado com as monografias; apresentação atual a conferir</td></tr><tr><td>PedWB</td><td>${s.topics} capítulos preservados</td><td>Consulta documental; aprovação clínica do corpus não declarada</td></tr><tr><td>Inventário diagnóstico</td><td>${s.diagnosticTerms} termos numerados extraídos</td><td>Lista original contém variantes inadequadas; sem conduta automática</td></tr><tr><td>Arquivos visuais</td><td>${s.pagesWithoutText} páginas sem texto extraível</td><td>Originais disponíveis. A busca textual não cobre informações em imagens</td></tr><tr><td>Prescrição</td><td>${regimens.length} esquemas com preenchimento automático</td><td>Seleção por indicação, idade e apresentação; cálculo e texto de administração vinculados às fontes</td></tr></tbody></table></div></section><section class="panel"><div class="panel-head"><h2>Achados na conferência dos anexos</h2></div><div class="panel-body"><div class="source-notice">O anexo “prompt MESTRE(2).pdf” é uma imagem de “GitHub Repo Card Template”, sem instruções clínicas. Foi preservado e identificado como documento visual.</div><p class="small-text muted">As transcrições DOCX contêm doses em imagens. Essas imagens permanecem na leitura visual; não foram convertidas silenciosamente em posologia operacional. O arquivo PedPresc Ágil contém apenas um esqueleto HTML, sem o gerador completo.</p><details><summary>Fontes com conteúdo visual ou fórmulas incorporadas</summary>${visual.map(v=>`<p class="small-text"><button class="text-button" data-source="${v.id}">${esc(v.title)}</button> · ${v.visualOnlyPages.length} páginas sem texto · ${v.embeddedImages||0} imagens incorporadas</p>`).join('')}</details><details><summary>Referências de segurança consultadas nesta construção</summary><p class="small-text">Verificação em 26/09/2026. Consulta dirigida, sem validação de todas as monografias.</p><p><a href="https://www.gov.br/anvisa/pt-br/centraisdeconteudo/publicacoes/servicosdesaude/publicacoes/protocolo-de-seguranca-na-prescricao-uso-e-administracao-de-medicamentos" target="_blank" rel="noopener noreferrer">Anvisa — segurança na prescrição, uso e administração de medicamentos</a></p><p><a href="https://www.cdc.gov/group-a-strep/hcp/clinical-guidance/strep-throat.html" target="_blank" rel="noopener noreferrer">CDC — faringite estreptocócica: indicação e esquema vinculados</a></p><p><a href="https://cps.ca/en/documents/position/pain-assessment-and-management" target="_blank" rel="noopener noreferrer">Canadian Paediatric Society — avaliação e manejo da dor</a></p></details><details><summary>Privacidade e funcionamento</summary><p>Os dados do atendimento ficam em memória apenas nesta aba; não são enviados a um servidor pelo aplicativo. Recarregar ou fechar a aba apaga o atendimento. O site não assina eletronicamente. O módulo conversacional envia os parâmetros ao backend; seu histórico técnico e estado de conexão aparecem em WhatsApp. O atendimento manual permanece nesta aba. A busca funciona sobre os documentos integrados; não pesquisa a Biblioteca do ChatGPT ou fontes externas em tempo real.</p></details></div></section>`);}

document.addEventListener('click',e=>{const b=e.target.closest('button,a');if(!b)return;const d=b.dataset;if(d.shareRegimen){shareRegimen(d.shareRegimen);return;}if(d.regimen){regimenDialog(d.regimen);return;}if(d.catalogDiagnosis){showCatalogDiagnosis(d.catalogDiagnosis);return;}if(d.guidance){showGuidance(d.guidance);return;}if(d.chooseDiagnosis){$('#patient-diagnosis').value=d.chooseDiagnosis;$('#patient-diagnosis').dispatchEvent(new Event('input',{bubbles:true}));closeDialog();navigate('prescricao');return;}if(d.med){showMedication(d.med);return;}if(d.medName){const m=state.meds.find(m=>norm(keyName(m.name))===norm(d.medName));if(m)showMedication(m.id);return;}if(d.chooseMed){chooseMedication(d.chooseMed);return;}if(d.configureMed){configureMedication(d.configureMed);return;}if(d.source){showSource(d.source,Number(d.sourcePage||1),d.mode||'text');return;}if(d.download){downloadSource(d.download);return;}if(d.topic){showTopic(d.topic);return;}if(d.searchTerm){searchTerm(d.searchTerm);return;}if(d.letter!==undefined){state.medLetter=d.letter;state.medPage=0;renderMeds();return;}if(d.page){const key={med:'medPage',source:'sourcePage',topic:'topicPage'}[d.page];state[key]+=Number(d.delta);({med:medResults,source:sourceResults,topic:topicResults}[d.page])();return;}if(d.topicMode){state.topicMode=d.topicMode;state.topicPage=0;renderTopics();return;}if(d.calc){state.calcMode=d.calc;if(state.route==='calculadoras')renderCalculators();else navigate('calculadoras');return;}if(d.editItem){configureMedication(null,d.editItem);return;}if(d.removeItem){state.notesReviewedRevision=-1;state.rx=state.rx.filter(x=>x.id!==d.removeItem);render();return;}if(d.action){({ 'manual-item':()=>configureMedication(),notes:notesDialog,'copy-rx':()=>exportRx(false),'print-rx':()=>exportRx(true),fulltext:()=>navigate('busca') }[d.action]||(()=>{}))();}});
$('#close-dialog').onclick=closeDialog;
$('#detail-dialog').addEventListener('click',e=>{if(e.target===$('#detail-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog();}});
$('#menu').onclick=()=>$('#sidebar').classList.toggle('open');
$('#patient-more').onclick=()=>{$('#patient-extra').hidden=!$('#patient-extra').hidden;};
$('#theme-toggle').onclick=()=>{document.body.classList.toggle('contrast');$('#theme-toggle').setAttribute('aria-pressed',String(document.body.classList.contains('contrast')));try{localStorage.setItem('nexo-contrast',document.body.classList.contains('contrast')?'1':'0');}catch{}};
try{if(localStorage.getItem('nexo-contrast')==='1')document.body.classList.add('contrast');}catch{}
$('#theme-toggle').setAttribute('aria-pressed',String(document.body.classList.contains('contrast')));
$('#global-search').onsubmit=e=>{e.preventDefault();const q=$('#global-query').value.trim();if(!q)return;requestSearch(q);navigate('busca');};
$('#new-patient').onclick=()=>{if(state.rx.length&&!window.confirm('Iniciar outro paciente? Os dados e itens deste atendimento serão apagados.'))return;resetConversation();$$('.patient-bar input,.patient-extra input,.patient-extra select,.clinical-context input').forEach(i=>{if(i.type==='checkbox')i.checked=false;else i.value='';});$('#patient-cough').value='none';$('#patient-setting').value='outpatient';$('#patient-respiratory-alarm').value='unknown';updateCoughFields();state.rx=[];state.notes={};state.notesReviewedRevision=-1;state.patientRevision++;closeDialog();navigate('prescricao');toast('Novo atendimento iniciado.');};
$$('.patient-bar input,.patient-extra input,.patient-extra select,.clinical-context input,.clinical-context select').forEach(i=>i.addEventListener('input',()=>{updateCoughFields();if(['patient-diagnosis','age-years','age-months','age-days','patient-setting'].includes(i.id)){state.notes={};state.notesReviewedRevision=-1;}state.patientRevision++;if(state.route==='prescricao')renderRx();if(state.route==='calculadoras'){$$('#calculator [id$="result"]').forEach(x=>x.innerHTML='<p class="inline-notes">Dados do paciente alterados. Calcule novamente.</p>');}}));
