function registerTools(){const c=document.modelContext;if(!c?.registerTool)return;const controller=new AbortController();const tool={name:'search_medication_catalog',title:'Pesquisar catálogo de medicamentos',description:'Consulta nomes e apresentações documentais. Não seleciona dose nem emite prescrição.',inputSchema:{type:'object',properties:{query:{type:'string',minLength:1,maxLength:150}},required:['query'],additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute(input){if(!input||typeof input.query!=='string'||!input.query.trim()||input.query.length>150)throw Error('Informe um termo de busca válido.');state.medQuery=input.query;state.medLetter='';state.medFilter='all';state.medPage=0;navigate('medicamentos');const hits=filteredMeds();return {count:hits.length,results:hits.slice(0,30).map(m=>({id:m.id,name:m.name,source:sourceTitle(m.source),status:'documental'}))};}};try{Promise.resolve(c.registerTool(tool,{signal:controller.signal})).catch(()=>{});}catch{}window.addEventListener('pagehide',()=>controller.abort(),{once:true});}
async function init(){try{const [manifest,meds,topics,diagnoses]=await Promise.all(['data/manifest.json','data/medications.json','data/topics.json','data/diagnoses.json'].map(getJSON));const canonicalIds=buildMedicationCanonicalMap(meds,medicationEvidence);Object.assign(state,{manifest,meds:meds.map(m=>{const canonicalId=canonicalIds.get(m.id)||m.id;return {...applyMedicationCorrection(m,canonicalId),name:medicationEvidence[m.id]?.name||m.name,canonicalMedicationId:canonicalId};}),topics,diagnoses,diagnosisCatalog:buildDiagnosisCatalog(guidanceRecords,[])});$('#diagnosis-options').innerHTML=[...new Set([...guidanceInputNames,...diagnoses.map(d=>d.name)])].sort((a,b)=>a.localeCompare(b,'pt-BR')).map(n=>`<option value="${esc(n)}"></option>`).join('');route();registerTools();loadPpsDiagnoses();}catch(e){setContent(`<div class="error">${esc(e.message)} Recarregue a página para tentar novamente.</div>`);}}
// ── Prescrição direta por diagnóstico ──────────────────────────────────────
// Recorded clinical-context inputs supply the patient-specific declarations.
// Diagnosis groups visible options; eligibility uses the recorded symptoms
// and care setting before calculation and final emission.
state.therapyTab=state.therapyTab||'etiologic';
const therapyTabLabels={etiologic:'Tratamento da causa',symptomatic:'Sintomáticos',support:'Medidas de suporte',adjunct:'Adicional / complementar'};
const therapyRespiratoryDiagnosis=p=>/(rinite|nasofaringite|resfriado|iv[aá]s|alerg|sinusite|laring|bronquite|crupe|pneumonia|tosse)/.test(norm(p.diagnosis));
const therapyDigestiveDiagnosis=p=>/(gastro|diarre|vomit|emese|nause|desidrat)/.test(norm(p.diagnosis));
function regimenLineLabel(r){const t=norm(r.title||'');if(r.line)return `${r.line}ª linha`;if(/primeira escolha|primeira linha/.test(t))return '1ª linha';if(/segunda linha|falha|alternativa/.test(t))return '2ª linha / alternativa';if(/terceira linha|resgate/.test(t))return '3ª linha / resgate';return '';}
function diagnosisTherapyChoices(group,p){
 return regimens.filter(r=>{
  if(group!=='symptomatic')return r.group===group&&regimenDiagnosisMatches(r,p.diagnosis);
  if(r.group!=='symptomatic')return false;
  const core=['analgesic','nsaid'].includes(r.family)||['dipirona','paracetamol','ibuprofeno','cetoprofeno'].includes(r.ingredient);
  const allergy=r.family==='antihistamine'&&therapyRespiratoryDiagnosis(p);
  const antiemetic=r.family==='antiemetic'&&therapyDigestiveDiagnosis(p);
  const cough=r.family==='antitussive'&&/(tosse|coqueluche|laring|bronquite|crupe)/.test(norm(p.diagnosis));
  return core||allergy||antiemetic||cough||(r.diagnoses?.length&&regimenDiagnosisMatches(r,p.diagnosis));
 }).sort((a,b)=>(a.line||99)-(b.line||99)||String(a.title).localeCompare(String(b.title),'pt-BR'));
}
function interactiveRegimenCard(r,choices){
 const e=regimenEligibility(r,patient()),line=regimenLineLabel(r),presentations=r.presentations?.length||0;
 const dose=['topical','instruction'].includes(r.delivery)?'Aplicação conforme a apresentação':r.delivery==='fluid'?'Volume de suporte por peso':r.doseBands?'Dose por faixa de idade/peso':r.phases?'Doses por etapa':r.basis==='fixed'?'Dose fixa por indicação':`${r.dose} ${r.unit==='U'?'UI':r.unit}/${r.basis==='kg-day'?'kg/dia':'kg/dose'}`;
 return `<article class="therapy-card clickable-therapy ${e.eligible?'':'is-not-ready'}" data-regimen="${esc(r.id)}" role="button" tabindex="0" aria-label="Selecionar ${esc(r.title)}"><div class="chipline">${pill(line||'Esquema documentado',line?'teal':'gray')}${pill(e.eligible?'Selecionar':'Consultar condições',e.eligible?'teal':'amber')}</div><h3>${esc(r.title)}</h3><p>${esc(r.name)}</p><p class="small-text">${esc(dose)}${r.interval?` · a cada ${fmt(r.interval)} h`:''}${r.single?' · dose única':''}</p><p class="small-text">${presentations} apresentação${presentations===1?'':'ões'} estruturada${presentations===1?'':'s'} · clique para escolher dose e forma</p><button class="button small outline" data-regimen="${esc(r.id)}">${e.eligible?'Selecionar':'Ver condições e apresentações'}</button></article>`;
}
function diagnosisTherapyHTML(){
 const p=patient(),hasDiagnosis=Boolean(p.diagnosis),active=state.therapyTab||'etiologic';
 const choices=hasDiagnosis?diagnosisTherapyChoices(active,p):[];
 const tabButtons=Object.entries(therapyTabLabels).map(([key,label])=>`<button class="${active===key?'active':''}" data-therapy-tab="${key}">${label}</button>`).join('');
 const supportFallback=active==='support'?`<div class="guidance-summary"><strong>Medidas não farmacológicas do diagnóstico</strong><p>Lavagem nasal, nebulização, hidratação, alimentação, compressas, imobilização, repouso, técnica de administração, evolução esperada, sinais de alarme e retorno são carregados pelo diagnóstico.</p><button class="button outline" data-action="notes">${icon('edit')}Revisar orientações completas</button></div>`:'';
 const adjunctFallback=active==='adjunct'?`<div class="guidance-summary"><strong>Uso adicional/complementar</strong><p>Inclui opções condicionais e off-label quando houver base documental. A seleção exige leitura da indicação, justificativa individual e revisão das contraindicações.</p><button class="button outline" data-action="notes">${icon('edit')}Revisar orientações e justificativas</button></div>`:'';
 return `<section class="panel diagnosis-therapy"><div class="panel-head"><div><div class="eyebrow">SELEÇÃO POR DIAGNÓSTICO</div><h2>Opções para este atendimento</h2><p>${hasDiagnosis?`O diagnóstico “${esc(p.diagnosis)}” organiza causa, sintomas, suporte e complementos. Clique no cartão para selecionar o esquema e inserir o cálculo na prévia.`:'Digite o diagnóstico para carregar as opções terapêuticas.'}</p></div></div><div class="panel-body"><div class="tabs therapy-tabs" role="tablist">${tabButtons}</div>${hasDiagnosis?`<div class="result-summary"><span>${choices.length} opção${choices.length===1?'':'ões'} nesta aba</span><span>Apresentações e posologias permanecem selecionáveis</span></div>${choices.length?`<div class="therapy-grid">${choices.map(r=>interactiveRegimenCard(r,choices)).join('')}</div>`:'<div class="empty"><h3>Nenhum esquema estruturado nesta aba</h3><p>Consulte a monografia e revise o plano individualizado antes de prescrever.</p></div>'}${supportFallback}${adjunctFallback}`:'<div class="empty"><h3>Aguardando diagnóstico</h3><p>Ao digitar a indicação, o site exibirá os esquemas correspondentes e as opções sintomáticas pertinentes.</p></div>'}<div class="guidance-summary"><strong>Orientações amplas do diagnóstico</strong><p>O receituário pode incluir cuidados gerais, evolução esperada, sinais de alarme e retorno conforme a ficha clínica selecionada.</p><button class="button outline" data-action="notes">${icon('edit')}Revisar orientações</button></div></div></section>`;
}
renderRx=function(){
 const items=state.rx.map(item=>{let text,status;try{const r=itemResult(item);text=preparedPrescriptionText(itemPrepared(item));status=item.reviewedRevision===state.patientRevision?pill(item.reviewProcess==='documental-and-math'?(r.mathOk===null?'Esquema e fontes vinculados':'Esquema e cálculo vinculados'):'Conferências registradas','teal'):pill('Rever após alteração','amber');}catch(e){text=e.message;status=pill('Rever dados','amber');}return `<div class="rx-item"><div class="item-icon">${icon('pill')}</div><div class="grow"><h3>${esc(item.name)}</h3><p>${esc(item.presentation)}</p><p><strong>${esc(text)}</strong></p><div class="chipline">${pill(item.route)}${status}</div></div><div class="rx-actions"><button class="icon-button" data-edit-item="${item.id}" aria-label="Editar ${esc(item.name)}">${icon('edit')}</button><button class="icon-button" data-remove-item="${item.id}" aria-label="Remover ${esc(item.name)}">${icon('trash')}</button></div></div>`;}).join('');
 const exportReady=canExportRx();let exportBlockReason='';if(!exportReady){try{ensureRx();}catch(e){exportBlockReason=e.message;}}
 const draft=exportReady?rxText({final:true}):'';
 const preview=draft?`<pre>${esc(draft)}</pre>`:state.rx.length||patient().diagnosis?`<p class="source-notice danger">${esc(exportBlockReason)} Nenhum bloco final operacional foi liberado.</p>`:'<h3>Receituário médico</h3><div class="paper-line"></div><div class="paper-placeholder"></div><div class="paper-placeholder short"></div><div class="paper-placeholder"></div><p class="muted small-text" style="margin-top:25px">Os itens selecionados aparecerão aqui.</p>';
 setContent(`<div class="dashboard-grid"><div>${diagnosisTherapyHTML()}<section class="panel"><div class="panel-head"><div><h2>Itens selecionados</h2><p>Cada item selecionado permanece vinculado à apresentação, posologia, limites e fonte.</p></div>${pill(String(state.rx.length)+' item'+(state.rx.length===1?'':'s'),'teal')}</div><div class="panel-body">${items||`<div class="empty"><div class="empty-icon">${icon('rx')}</div><h3>Nenhuma medicação selecionada</h3><p>Escolha um cartão acima ou pesquise no catálogo para iniciar.</p><button class="button soft" data-action="manual-item">${icon('plus')}Adicionar medicamento</button></div>`}${state.rx.length?'<div class="button-row"><button class="button soft" data-action="manual-item">'+icon('plus')+'Adicionar medicamento</button></div>':''}<div class="search-input" style="margin-top:22px">${icon('search')}<input id="rx-med-search" placeholder="Pesquisar medicamento no catálogo…" aria-label="Buscar medicamento para prescrição"></div><div id="rx-search-results"></div></div></section></div><div><section class="panel"><div class="panel-head"><h2>Prévia do receituário</h2>${pill(exportReady?'Pronto para copiar/revisar':'Rascunho — revisão necessária',exportReady?'teal':'amber')}</div><div class="panel-body"><div class="rx-paper"><div class="paper-label">PRESCRIÇÃO INTEGRAL</div>${preview}</div>${!exportReady&&exportBlockReason?`<p class="source-notice amber">${esc(exportBlockReason)}</p>`:''}<div class="button-row fill"><button class="button outline" data-action="copy-rx" ${exportReady?'':'disabled'}>${icon('copy')}Copiar bloco final</button><button class="button" data-action="print-rx" ${exportReady?'':'disabled'}>${icon('print')}Imprimir</button></div></div></section><section class="panel"><div class="panel-head"><h2>Atalhos de cálculo</h2><a href="#calculadoras" class="text-button">Abrir calculadoras ${icon('arrow')}</a></div><div class="panel-body quick-grid" style="margin-top:0"><button class="quick-card" data-calc="infusion"><span class="qicon">${icon('drop')}</span><span>Infusão contínua<small>mcg/kg/min → mL/h</small></span></button><button class="quick-card" data-calc="intermittent"><span class="qicon">${icon('clock')}</span><span>Infusão intermitente<small>Volume e tempo</small></span></button></div></section></div></div>${stats()}`);
 $('#rx-med-search').addEventListener('input',e=>{const q=norm(e.target.value.trim());$('#rx-search-results').innerHTML=q?state.meds.filter(m=>norm(m.name).includes(q)).slice(0,12).map(m=>`<div class="list-row"><div class="grow"><h3>${esc(m.name)}</h3><p>${m.presentations.length?'Apresentações documentadas':'Monografia disponível'}</p></div><button class="button small soft" data-med="${m.id}">${regimensForMedication(m.id).length?'Selecionar posologia':'Consultar monografia'}</button></div>`).join(''):'';});
};
document.addEventListener('click',e=>{const card=e.target.closest('article.clickable-therapy[data-regimen]');if(card&&!e.target.closest('button'))regimenDialog(card.dataset.regimen);const tab=e.target.closest('[data-therapy-tab]');if(tab){state.therapyTab=tab.dataset.therapyTab;render();}});
document.addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.matches('article.clickable-therapy[data-regimen]')){e.preventDefault();regimenDialog(e.target.dataset.regimen);}});
init();

let conversationSession=null,conversationLog=[],conversationEpoch=0,conversationBusy=false;
function resetConversation(){conversationEpoch++;conversationSession=null;conversationLog=[];conversationBusy=false;}
async function api(path,method='GET',body){const r=await fetch(path,{method,headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined});let d;try{d=await r.json();}catch{throw Error('Resposta indisponível. Atualize a página e tente novamente.');}if(!r.ok)throw Error(d.error||'Não foi possível concluir a operação.');return d;}
function personalWhatsApp(status){
 const p=status.profile,ready=status.enabled&&status.configured&&status.dbReady;
 const command=p?.linkCommand;
 const destination=ready&&status.businessNumber?`https://wa.me/${status.businessNumber}?text=${encodeURIComponent(p?.verified?'Olá':command||'Olá')}`:null;
 return `<section class="panel"><div class="panel-head"><div><h2>Qual é o seu WhatsApp?</h2><p>Cadastre o seu número pessoal ou profissional, usado por você como médico.</p></div>${pill(p?.verified?'Número confirmado':p?'Número salvo':'Cadastrar meu número',p?.verified?'teal':'amber')}</div><form class="panel-body" id="wa-profile-form"><p>Você poderá enviar peso, idade e diagnóstico pelo seu WhatsApp e receber o atendimento da plataforma na conversa, com os protocolos revisados disponíveis.</p><div class="form-grid two"><label for="wa-own-phone">Meu número de WhatsApp<input id="wa-own-phone" name="phone" type="tel" inputmode="tel" autocomplete="tel" maxlength="32" placeholder="+55 (DDD) 9XXXX-XXXX" value="${esc(p?.phone?'+'+p.phone:'')}" aria-describedby="wa-phone-help" required ${status.profileReady?'':'disabled'}></label><div><p id="wa-phone-help" class="small-text muted">Informe o DDD e os nove dígitos do seu celular. Este campo é para o seu número, não para o número do paciente nem para o número empresarial da plataforma.</p></div></div><label class="wa-owner-confirm"><input id="wa-own-confirm" type="checkbox" required>Confirmo que este WhatsApp é meu e quero usá-lo para acessar a plataforma.</label><div id="wa-profile-feedback" role="status" aria-live="polite"></div><div class="button-row"><button class="button" type="submit" ${status.profileReady?'':'disabled'}>${p?'Salvar meu WhatsApp':'Cadastrar meu WhatsApp'}</button><button class="button outline" id="wa-refresh" type="button">Atualizar status</button></div>${!status.profileReady?'<p class="error">Não foi possível carregar seu cadastro. Atualize o status para tentar novamente.</p>':''}${p?`<p class="inline-notes">Seu número está salvo na sua conta e será mantido ao sair do site. ${p.verified?'A confirmação deste número já foi recebida.':'A confirmação será feita a partir do próprio WhatsApp.'}</p>`:''}<div class="source-notice">${ready?(p?.verified?'Número confirmado. O atendimento por mensagem usa os mesmos protocolos revisados do site.':p?'Próximo passo: confirme seu número enviando o comando de vínculo abaixo ao WhatsApp da plataforma.':'Cadastre seu WhatsApp acima para preparar a confirmação do seu número.'):'O canal da plataforma ainda aguarda ativação. Você já pode salvar seu número; o cadastro, sozinho, ainda não libera respostas pelo WhatsApp.'}</div>${ready&&p&&!p.verified?(command?`<p>Envie do seu WhatsApp cadastrado: <code>${esc(command)}</code></p><p class="inline-notes">Código válido até ${esc(new Date(p.linkExpires).toLocaleString('pt-BR'))}. Guarde-o apenas para vincular o seu número.</p><button class="button outline" type="button" id="wa-copy-link">Copiar comando de vínculo</button>`:'<p>O código de vínculo expirou. Confirme a caixa acima e salve novamente para gerar outro.</p>'):''}${destination&&(p?.verified||command)?`<div class="button-row"><a class="button" href="${esc(destination)}" target="_blank" rel="noopener noreferrer">Abrir WhatsApp da plataforma</a></div>`:''}${ready&&!status.businessNumber?'<p class="inline-notes">O número de atendimento da plataforma ainda precisa ser informado na configuração do canal para exibir o botão de conversa.</p>':''}<p class="small-text muted">Após a ativação e a confirmação do número, exemplo de mensagem: “Peso 18 kg, idade 4 anos, diagnóstico otite média aguda”.</p></form></section>`;
}
function chatLog(){return conversationLog.map(x=>`<div class="chat-bubble ${x.from==='you'?'sent':''}"><strong>${x.from==='you'?'Você':'PRESCRIÇÃO INTEGRAL'}</strong><br>${esc(x.text)}</div>`).join('')||'<div class="empty">Informe os dados sem nome ou documento do paciente. O mesmo motor será usado pelo WhatsApp quando a conexão estiver ativa.</div>';}
async function renderWhatsApp(){setContent('<div class="loading"><span class="spinner"></span>Carregando configuração do canal…</div>');let status,protocols;
 try{[status,protocols]=await Promise.all([api('/api/whatsapp/status'),api('/api/protocols')]);if(state.route!=='whatsapp')return;}catch(e){if(state.route==='whatsapp')setContent(`<div class="error">${esc(e.message)}</div><button class="button" id="wa-retry">Tentar novamente</button>`);$('#wa-retry')?.addEventListener('click',renderWhatsApp);return;}
 setContent(`${personalWhatsApp(status)}<div class="audit-cards"><div class="audit-card">${pill(status.enabled&&status.configured?'Aguardando teste real':'Pendente de ativação','amber')}<h3 style="margin:14px 0">Canal da plataforma</h3><p>${status.profile?'Seu WhatsApp cadastrado: '+esc(status.profile.masked):'Cadastre seu WhatsApp no formulário acima.'}</p><p class="inline-notes">Seu número de acesso e o canal da plataforma têm configurações separadas.</p></div><div class="audit-card">${pill('Motor central','teal')}<h3 style="margin:14px 0">${status.protocolCount} protocolos revisados</h3><p>Site e WhatsApp consultam os mesmos esquemas e a mesma rotina matemática.</p><p class="inline-notes">${esc(status.engineVersion)}</p></div><div class="audit-card">${pill('Não concluído','amber')}<h3 style="margin:14px 0">Teste de ponta a ponta</h3><p>A integração exige uma mensagem real e a resposta recebida no WhatsApp. Nenhum teste real foi confirmado.</p></div></div><div class="dashboard-grid"><div><section class="panel"><div class="panel-head"><h2>Atendimento por mensagem</h2><button class="button small outline" id="chat-new">/nova</button></div><form class="panel-body" id="chat-form"><p class="inline-notes" style="margin-bottom:16px">Conversa pelo site com o motor central. Este painel não simula uma mensagem recebida no WhatsApp.</p><div class="chat-log" id="chat-log">${chatLog()}</div><label>Mensagem<textarea id="chat-message" placeholder="Peso 18 kg, idade 4 anos, diagnóstico otite média aguda." required></textarea></label><div id="chat-error"></div><div class="button-row"><button class="button" type="submit">Enviar ao motor</button><button class="button outline" type="button" id="chat-confirm">Confirmar dados</button></div><p class="inline-notes">Alergias, comorbidades e funções renal/hepática omitidas permanecem não informadas. Registre ausência apenas quando conhecida e explicitamente informada. Dados ausentes ou desconhecidos não habilitam prescrição automática. A geração exige protocolo revisado e orientações completas.</p></form></section><section class="panel"><div class="panel-head"><h2>Protocolos compartilhados</h2><button class="button small" id="add-protocol">Revisar novo esquema</button></div><div class="panel-body">${protocols.map(p=>`<div class="list-row"><div class="grow"><h3>${esc(p.diagnosis)}</h3><p>${esc(p.name)} · ${esc(p.presentation)}</p><p class="inline-notes">Revisado: ${esc(new Date(p.version).toLocaleString('pt-BR'))}</p></div><button class="button small outline" data-protocol-id="${p.id}">Editar</button><button class="icon-button" data-disable-protocol="${p.id}" aria-label="Desativar esquema">${icon('trash')}</button></div>`).join('')||'<div class="empty">O acervo documental não foi aprovado automaticamente como conjunto de protocolos. Cadastre apenas esquemas cuja indicação, faixa etária, apresentação, máximos e restrições tenham sido revisados.</div>'}</div></section></div><aside><section class="panel"><div class="panel-head"><h2>Ativação do canal oficial</h2></div><div class="panel-body"><ol class="channel-steps"><li>Vincular um número empresarial à WhatsApp Cloud API da Meta.</li><li>Configurar credenciais da Meta no ambiente protegido do servidor.</li><li>Disponibilizar o webhook para a Meta, mantendo as fontes e os atendimentos privados.</li><li>Assinar os eventos de mensagens e confirmar o recebimento.</li><li>Enviar uma mensagem do número autorizado e verificar a resposta no aparelho.</li></ol><p class="source-notice">A ativação depende das credenciais empresariais e de uma rota acessível à Meta. O site privado exige autenticação do ChatGPT e não deve ser tornado público apenas para liberar o webhook.</p><details><summary>Configuração técnica pendente</summary><p class="small-text">Chaves ausentes: ${status.missing.map(esc).join(', ')||'nenhuma'}</p><p class="small-text">Webhook: <code>${esc(status.webhookPath)}</code></p><p class="small-text">Não coloque tokens em formulários clínicos, mensagens ou código do navegador. Configure-os como segredos de produção.</p></details><p><a href="https://developers.facebook.com/documentation/business-messaging/whatsapp/get-started" target="_blank" rel="noopener noreferrer">Configuração oficial da Meta ↗</a></p></div></section><section class="panel"><div class="panel-head"><h2>Auditoria do canal</h2></div><div class="panel-body">${status.audit.map(a=>`<div class="list-row"><div><strong>${esc(a.code)}</strong><p class="small-text">${esc(new Date(a.created).toLocaleString('pt-BR'))}</p><p class="inline-notes">${esc(a.engine)}</p></div></div>`).join('')||'<p class="muted">Nenhum evento real registrado.</p>'}<p class="inline-notes">Sessões: 15 minutos. Mensagens criptografadas para controle de entrega: até 24 h. Auditoria técnica sem texto clínico: até 30 dias. A limpeza ocorre no próximo evento recebido. Áudio e PDF pelo canal não estão habilitados.</p></div></section></aside></div>`);
 $('#wa-profile-form').onsubmit=async e=>{e.preventDefault();const form=e.currentTarget,button=form.querySelector('button[type=submit]'),feedback=$('#wa-profile-feedback');button.disabled=true;feedback.textContent='Salvando seu WhatsApp…';try{await api('/api/whatsapp/profile','POST',{phone:$('#wa-own-phone').value,confirmOwnNumber:$('#wa-own-confirm').checked});if(state.route==='whatsapp'){await renderWhatsApp();toast('Seu WhatsApp foi salvo na sua conta.');}}catch(err){if(feedback.isConnected)feedback.innerHTML='<p class="error">'+esc(err.message)+'</p>';}finally{if(button.isConnected)button.disabled=false;}};
 $('#wa-refresh').onclick=()=>renderWhatsApp();$('#wa-copy-link')?.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(status.profile.linkCommand);toast('Comando copiado. Envie pelo seu WhatsApp.');}catch{toast('Copie o comando exibido acima.');}});
 const submit=async text=>{text=text.trim();if(!text)return;const isReset=['/nova','/cancelar'].includes(text);if(isReset)resetConversation();else if(conversationBusy){toast('Aguarde a resposta antes de continuar este atendimento.');return;}const epoch=conversationEpoch;conversationBusy=true;const btn=$('#chat-form button[type=submit]');btn.disabled=true;$('#chat-error').innerHTML='';try{const d=await api('/api/clinical','POST',{message:text,session:conversationSession});if(epoch!==conversationEpoch)return;conversationSession=d.session;conversationLog.push({from:'you',text},{from:'nexo',text:d.text});if(state.route==='whatsapp'&&$('#chat-log')){$('#chat-log').innerHTML=chatLog();$('#chat-log').scrollTop=$('#chat-log').scrollHeight;$('#chat-message').value='';}}catch(e){if(epoch===conversationEpoch&&$('#chat-error'))$('#chat-error').innerHTML='<div class="error">'+esc(e.message)+'</div>';}finally{if(epoch===conversationEpoch){conversationBusy=false;const active=$('#chat-form button[type=submit]');if(active)active.disabled=false;}}};
 $('#chat-form').onsubmit=e=>{e.preventDefault();submit($('#chat-message').value);};$('#chat-new').onclick=()=>submit('/nova');$('#chat-confirm').onclick=()=>submit('confirmar');$('#add-protocol').onclick=()=>protocolDialog();$$('[data-protocol-id]').forEach(b=>b.onclick=()=>protocolDialog(protocols.find(p=>p.id===b.dataset.protocolId)));$$('[data-disable-protocol]').forEach(b=>b.onclick=async()=>{if(!confirm('Desativar este esquema nos dois canais?'))return;try{await api('/api/protocols','POST',{action:'disable',id:b.dataset.disableProtocol});renderWhatsApp();}catch(e){toast(e.message);}});
}
function protocolDialog(p={}){openDialog('Revisão do protocolo compartilhado',`<form id="protocol-form"><div class="source-notice">Um protocolo só deve ser habilitado depois de revisão clínica e farmacêutica. A automação desta versão atende esquemas orais, dentro da faixa etária definida, com alergias, comorbidades e funções renal/hepática explicitamente informadas. Omissão ou desconhecimento não equivale a ausência ou função normal e não habilita prescrição automática. Condições adicionais serão confirmadas pelo prescritor antes do cálculo.</div><div class="protocol-grid"><label>Diagnóstico normalizado<input id="protocol-dx" value="${esc(p.diagnosis||'')}" placeholder="Ex.: otite média aguda" required></label><label>Medicamento do catálogo<select id="protocol-med">${state.meds.map(m=>`<option value="${m.id}" ${p.medicationId===m.id?'selected':''}>${esc(m.name)}</option>`).join('')}</select></label><label class="span-2">Apresentação completa<input id="protocol-presentation" value="${esc(p.presentation||'')}" required></label>${inputField('protocol-min','Idade mínima · meses',p.minMonths??'','inputmode="decimal"')}${inputField('protocol-max','Idade máxima · meses',p.maxMonths??'','inputmode="decimal"')}${inputField('protocol-duration','Duração',p.duration||'')}${inputField('protocol-reference','Fonte específica, página e versão',p.reference||'')}<label class="span-2">Condições para indicar este esquema<textarea id="protocol-conditions" required>${esc(p.conditions||'')}</textarea></label><label class="span-2">Contraindicações, interações e restrições<textarea id="protocol-contraindications" required>${esc(p.contraindications||'')}</textarea></label><label class="span-2">Instruções do medicamento<textarea id="protocol-instructions" required>${esc(p.instructions||'')}</textarea></label><div class="span-2"><h3>Orientações obrigatórias do receituário</h3><p class="inline-notes">Todos os blocos serão incluídos no resultado. Revise-os para a indicação, faixa etária e contexto deste protocolo.</p><button class="button small outline" type="button" id="protocol-fill-guidance">Carregar rascunho pelo diagnóstico</button></div>${guidanceFields.map(([k,l])=>`<label class="span-2">${l}<textarea id="protocol-guidance-${k}" required maxlength="3000">${esc(p.guidance?.[k]||'')}</textarea></label>`).join('')}</div><h3 style="margin:24px 0 16px">Dose, concentração e máximos</h3>${doseFields('protocol-',p.form||{})}<div class="check-group"><label class="check-label"><input type="checkbox" id="protocol-review-clinical" required>Revisei indicação, faixa etária, duração, máximos, contraindicações e orientações na fonte citada.</label><label class="check-label"><input type="checkbox" id="protocol-review-pharmacy" required>Revisei princípio ativo, apresentação, concentração, via oral e mensurabilidade.</label></div><div id="protocol-error"></div><button class="button" type="submit">Salvar protocolo revisado nos dois canais</button></form>`,'GOVERNANÇA CLÍNICA');
 if(p.regimenId){$('#protocol-med').disabled=true;for(const k of ['presentation','duration'])$('#protocol-'+k).readOnly=true;for(const k of ['basis','dose','unit','amount','concentrationUnit','volume','interval','step','maxDose','maxDay','maxKgDay','dropFactor','single'])$('#protocol-'+k).disabled=true;}
 $('#protocol-fill-guidance').onclick=()=>{const g=guidanceFor($('#protocol-dx').value,Number($('#protocol-min').value));if(g.branchPending){toast('Selecione o subtipo/contexto no atendimento e revise as orientações antes de compartilhar o protocolo.');return;}if(!g.matched){toast('Preencha as orientações individualmente para esta indicação e faixa etária.');return;}if(guidanceFields.some(([k])=>$('#protocol-guidance-'+k).value.trim())&&!window.confirm('Substituir o rascunho de orientações preenchido?'))return;for(const [k] of guidanceFields)$('#protocol-guidance-'+k).value=g[k];toast('Rascunho carregado. Confira a aplicação a toda a faixa etária do protocolo e cite as fontes.');};
 $('#protocol-form').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button[type=submit]');button.disabled=true;try{const med=state.meds.find(m=>m.id===$('#protocol-med').value);const input={id:p.id,regimenId:p.regimenId,regimenPresentation:p.regimenPresentation,regimenDuration:p.regimenDuration,therapyVersion:p.therapyVersion,diagnosis:$('#protocol-dx').value,medicationId:med.id,name:med.name,presentation:$('#protocol-presentation').value,minMonths:$('#protocol-min').value,maxMonths:$('#protocol-max').value,duration:$('#protocol-duration').value,reference:$('#protocol-reference').value,conditions:$('#protocol-conditions').value,contraindications:$('#protocol-contraindications').value,instructions:$('#protocol-instructions').value,guidance:Object.fromEntries(guidanceFields.map(([k])=>[k,$('#protocol-guidance-'+k).value])),route:'ORAL',form:readDose('protocol-'),reviewClinical:$('#protocol-review-clinical').checked,reviewPharmacy:$('#protocol-review-pharmacy').checked};delete input.form.weight;await api('/api/protocols','POST',input);closeDialog();renderWhatsApp();toast('Protocolo salvo na fonte central dos dois canais.');}catch(err){$('#protocol-error').innerHTML='<div class="error">'+esc(err.message)+'</div>';}finally{button.disabled=false;}};
}

function updateCoughFields(){const has=$('#patient-cough').value!=='none';$('#cough-days-label').hidden=!has;$('#respiratory-alarm-label').hidden=!has;}
function regimenEcard(r){return r.ecard?`<figure class="therapy-ecard"><img src="${esc(r.ecard.src)}" alt="${esc(r.ecard.alt)}" loading="lazy"><figcaption>${esc(r.ecard.alt)}</figcaption></figure>`:'';}
function regimenNotice(id){const r=regimens.find(r=>r.id===id);return r?`<div class="source-notice"><strong>${esc(r.title)}</strong>${regimenEcard(r)}<p>${esc(r.conditions)}</p><p>${esc(r.contraindications)}</p><p>${esc(r.offLabel)}</p><p class="small-text">${THERAPY_VERSION} · rascunho documental para conferência individual.</p></div>`:'';}
function regimenCard(r){const e=regimenEligibility(r,patient());return `<article class="therapy-card"><div class="chipline">${pill(therapyGroups[r.group])}${pill(e.eligible?'Calcular e revisar':'Ver condições',e.eligible?'teal':'gray')}</div><h3>${esc(r.title)}</h3>${regimenEcard(r)}<p>${esc(r.name)}</p><p class="small-text">${['topical','instruction'].includes(r.delivery)?'Aplicação conforme a apresentação':r.delivery==='fluid'?(r.fluidBasis==='kg-course'?'Volume inicial de reidratação por peso':'Reposição oral conforme a idade'):r.doseBands?'Dose por faixa de idade/peso':r.phases?'Doses por etapa do tratamento':r.basis==='fixed'?'Dose fixa por indicação':`${r.dose} ${r.unit==='U'?'UI':r.unit}/${r.basis==='kg-day'?'kg/dia':'kg/dose'}`} ${['topical','instruction','fluid'].includes(r.delivery)?'':r.acuteCourse?'· curso agudo supervisionado':r.schedule?'· '+esc(r.schedule):r.single?'· dose única':'· '+r.interval+' h'}</p><button class="button small outline" data-regimen="${r.id}">${e.eligible?'Selecionar esquema':'Consultar esquema'}</button></article>`;}
function regimensForMedication(id){const canonicalId=state.meds.find(m=>m.id===id)?.canonicalMedicationId||id;return regimens.filter(r=>r.medicationId===canonicalId);}
function chooseMedication(id){const m=state.meds.find(x=>x.id===id);if(!m)return;if(regimensForMedication(id).length)openDialog(m.name,medRegimensHTML(id),'SELECIONAR POSOLOGIA');else configureMedication(id);}
function medRegimensHTML(id){const rs=regimensForMedication(id);return `<section class="regimen-section"><h3>Posologias estruturadas</h3>${rs.length?`<p class="inline-notes">Cálculo vinculado à indicação, faixa etária, apresentação e máximos.</p><div class="therapy-grid">${rs.map(regimenCard).join('')}</div>`:'<p>Monografia integral disponível abaixo. O cálculo manual deste fármaco está suspenso sem vínculo documental canônico; sua monografia permanece disponível para consulta.</p>'}</section>`;}
function therapyPlanHTML(){const p=patient(),g=currentGuidance(),ca=coughAssessment(p),dx=norm(p.diagnosis);const rs=regimens.filter(r=>r.family==='antitussive'?p.coughType!=='none':r.symptom==='pain'?p.pain:r.symptom==='vomiting'?p.vomiting&&regimenDiagnosisMatches(r,p.diagnosis):regimenDiagnosisMatches(r,p.diagnosis));return `<section class="panel therapy-plan"><div class="panel-head"><div><div class="eyebrow">PLANO CLÍNICO INTEGRADO</div><h2>Uma prescrição completa, por indicação</h2></div></div><div class="panel-body">${p.diagnosis?`<div class="guidance-summary"><strong>${esc(p.diagnosis)}</strong><p>${g.matched?'Orientações específicas disponíveis para revisão.':'Selecione um diagnóstico da busca ou individualize as orientações.'}</p>${g.setting&&g.setting!=='home'?`<p class="warning-text">Contexto da referência: ${esc({urgent:'avaliação urgente',hospital:'atendimento hospitalar',specialist:'acompanhamento especializado'}[g.setting])}. A emissão não comprova critérios de alta.</p>`:''}<button class="text-button" data-action="notes">Revisar cuidados e retorno ${icon('arrow')}</button></div>`:''}${p.coughType!=='none'?`<div class="source-notice ${ca.urgent?'danger':''}"><strong>${esc(coughTypes[p.coughType])}</strong><p>${esc(ca.message)}</p><a href="https://www.rch.org.au/clinicalguide/guideline_index/cough/" target="_blank" rel="noopener noreferrer">Diretriz pediátrica de tosse ↗</a></div>`:''}<div class="therapy-sections">${Object.entries(therapyGroups).map(([group,title])=>{const choices=rs.filter(r=>r.group===group);return `<details class="therapy-group" ${choices.length?'open':''}><summary>${title}<span>${choices.length?choices.length+' opções':'Individualizar'}</span></summary>${choices.length?`<div class="therapy-grid">${choices.map(regimenCard).join('')}</div>`:group==='support'?`<p>Cuidados do diagnóstico, hidratação/alimentação apropriadas, técnica de administração e retorno são preenchidos no bloco de orientações. Restrições hídricas e suporte respiratório exigem definição individual.</p><button class="button small outline" data-action="notes">Revisar suporte e cuidados</button>`:group==='adjunct'?`<p>Acrescente apenas tratamentos com indicação adicional definida. Off-label exige evidência, justificativa, acompanhamento e informação ao responsável. Não há inclusão automática de vitaminas, probióticos, corticoides ou combinações.</p><button class="button small outline" data-action="manual-item">Adicionar tratamento individual</button>`:`<p>${group==='etiologic'?'Nenhum esquema estruturado corresponde ao diagnóstico informado. Consulte os capítulos e monografias para definir o tratamento da causa.':'Marque os sintomas avaliados para consultar opções ou individualize o esquema.'}</p>`}</details>`;}).join('')}</div></div></section>`;}
function preparedResultHTML(prepared){
 const phases=prepared.phases||[{result:prepared.result,duration:prepared.duration}];
 return `<div class="results-box"><strong>Texto que será incluído na receita</strong><pre class="monograph" style="white-space:pre-wrap">${esc(preparedPrescriptionText(prepared))}</pre><p>${esc(prepared.instructions||'')}</p>${prepared.course?`<p class="small-text">Limite deste curso: até ${prepared.course.maximumAdministrations} administrações (${fmt(prepared.course.maximumTotal,4)} ${esc(prepared.course.unit)} somadas), ${esc(prepared.course.window)}. Descontar as doses já recebidas; não executar todas as etapas se não forem necessárias.</p>`:''}${phases.map(phase=>{const r=phase.result;if(['topical','instruction'].includes(r.kind))return '<p class="small-text">Quantidade, local e frequência de administração conforme a apresentação e a fonte vinculada.</p>';if(r.kind==='fluid')return `<p class="small-text">${r.basis==='kg-course'?`Faixa inicial documentada: ${fmt(r.minVolume,2)}–${fmt(r.maxVolume,2)} mL (${fmt(r.reverseMin)}–${fmt(r.reverseMax)} mL/kg). Volume médio calculado: ${fmt(r.targetVolume,2)} mL; conferência reversa: ${fmt(r.reverseTarget)} mL/kg. Reavaliar durante a oferta; não repetir como dose periódica.`:'Volume por evacuação líquida conforme a faixa etária; oferecer conforme aceitação e reavaliar hidratação.'}</p>`;return `<p class="small-text">${phase.label?esc(phase.label)+' · ':''}Dose por administração: ${r.components?r.components.map(c=>fmt(c.amount,4)+' '+esc(r.unit)+' de '+esc(c.name)).join(' + '):fmt(r.administered,4)+' '+esc(r.unit==='U'?'UI':r.unit)}. ${prepared.course||prepared.acuteRescue?'Resgate agudo com repetição condicional; não corresponde a dose diária contínua.':`Total por 24 h no esquema: ${r.components?r.components.map(c=>fmt(c.amount*r.times,4)+' '+esc(r.unit)+' de '+esc(c.name)).join(' + '):fmt(r.perDay,4)+' '+esc(r.unit==='U'?'UI':r.unit)}.`} Dose reversa: ${fmt(r.perKgDose,4)} ${esc(r.unit==='U'?'UI':r.unit)}/kg/dose${prepared.doseComponent?' de '+esc(prepared.doseComponent):''}. Arredondamento: ${fmt(r.delta,2)}%. ${r.cappedByLimit?'Teto da referência aplicado.':''}${r.nebulization?` Volume final: ${fmt(r.nebulization.finalVolume,4)} mL. Concentração final: ${fmt(r.nebulization.finalConcentration,4)} ${esc(r.unit)}/mL; cálculo reverso do preparo: ${fmt(r.nebulization.reverseDose,4)} ${esc(r.unit)}.`:''}</p>`;}).join('')}</div>`;
}
function regimenDialog(id,editId=null,previous=null){
 const r=regimens.find(r=>r.id===id);if(!r)return;
 const eligibility=regimenEligibility(r,patient());
 const previousChecks=previous?.reviewedRevision===state.patientRevision?(previous.regimenChecks||[]):[];
 const selectedChecks=()=>Array.from(document.querySelectorAll('[data-regimen-clinical-check]:checked')).map(el=>el.dataset.regimenClinicalCheck);
 const checkedPatient=()=>({...patient(),regimenChecks:selectedChecks()});
 const defaultReason=`Indicação informada: ${patient().diagnosis}. Esquema selecionado: ${r.title}. Fundamentação: ${r.conditions} ${r.offLabel}`;
 const previousReason=String(previous?.rationale||'').trim();
 const rationale=r.requiresReason?(previousReason===defaultReason.trim()?'':previousReason):(previous?.rationale||defaultReason);
 openDialog(r.title,`${regimenNotice(id)}<form id="regimen-form"><label>Apresentação<select id="regimen-presentation">${r.presentations.map((v,i)=>`<option value="${i}" ${i===(previous?.regimenPresentation||0)?'selected':''}>${esc(v.label)}</option>`).join('')}</select></label>${r.durationOptions?`<label>Duração conforme o contexto<select id="regimen-duration" required><option value="">Selecione a duração</option>${r.durationOptions.map(d=>`<option ${d===(previous?.regimenDuration||r.defaultDuration)?'selected':''}>${esc(d)}</option>`).join('')}</select></label>`:''}${!eligibility.eligible?`<div class="error">${eligibility.reasons.map(esc).join('<br>')}</div>`:''}${r.requiredClinicalChecks?.length?`<div class="check-group"><p>Condições clínicas para este esquema</p>${r.requiredClinicalChecks.map(c=>`<label class="check-label"><input type="checkbox" data-regimen-clinical-check="${esc(c.id)}" ${previousChecks.includes(c.id)?'checked':''} required>${esc(c.label)}</label>`).join('')}</div>`:''}<div id="regimen-preview" aria-live="polite"></div>${r.requiresReason?`<label>Justificativa individual do tratamento<textarea id="regimen-rationale" maxlength="2200" minlength="20" required>${esc(rationale)}</textarea></label><p class="small-text">Registre a indicação e a adequação do tratamento para este atendimento. O texto automático do esquema não substitui a justificativa individual; o sistema não registra uma conferência humana que não ocorreu.</p>`:`<details><summary>Fundamentação e ajustes opcionais</summary><label>Fundamentação documental<textarea id="regimen-rationale" maxlength="2200">${esc(rationale)}</textarea></label><p class="small-text">O conteúdo e os cálculos vêm do esquema vinculado às fontes. Ao selecionar, você define a adequação ao atendimento; o sistema não registra uma conferência humana que não ocorreu.</p></details>`}<div id="regimen-error"></div><div class="button-row"><button class="button" type="submit" ${eligibility.eligible?'':'disabled'}>${editId?'Atualizar item calculado':'Adicionar ao receituário'}</button><button class="button outline" type="button" data-configure-med="${r.medicationId}">Personalizar esquema</button></div><details class="guidance-sources"><summary>Fontes para conferência</summary>${r.sources.map(u=>`<p><a href="${esc(u)}" target="_blank" rel="noopener noreferrer">${esc(new URL(u).hostname)} ↗</a></p>`).join('')}<p class="small-text">${r.reviewedAt?'Revisão documental: '+esc(r.reviewedAt):'Esquema documental da versão '+esc(THERAPY_VERSION)}.</p></details></form>`,'TERAPÊUTICA · PREENCHIMENTO AUTOMÁTICO');
 const preview=()=>{if(!eligibility.eligible)return;try{assertConfirmedHistory(patient());const p=prepareRegimen(id,checkedPatient(),Number($('#regimen-presentation').value),$('#regimen-duration')?.value||'');$('#regimen-preview').innerHTML=preparedResultHTML(p);}catch(e){$('#regimen-preview').innerHTML='<div class="error">'+esc(e.message)+'</div>';}};
 $('#regimen-presentation').onchange=preview;$('#regimen-duration')?.addEventListener('change',preview);document.querySelectorAll('[data-regimen-clinical-check]').forEach(el=>el.addEventListener('change',preview));preview();
 $('#regimen-form').onsubmit=e=>{e.preventDefault();try{
  assertConfirmedHistory(patient());validatePatientAge();const index=Number($('#regimen-presentation').value),durationChoice=$('#regimen-duration')?.value||'',p=prepareRegimen(id,checkedPatient(),index,durationChoice);
  const item={id:editId||newItemId(),name:p.name,medId:p.medicationId,indication:patient().diagnosis,presentation:p.presentation,duration:p.duration,reference:p.reference,route:p.route,instructions:p.instructions,form:p.form||null,calculation:p.calculation||null,regimenId:id,regimenPresentation:index,regimenDuration:durationChoice,regimenChecks:selectedChecks(),group:p.group,rationale:r.requiresReason?$('#regimen-rationale').value.trim():($('#regimen-rationale').value.trim()||defaultReason),offLabel:p.offLabel,reviewProcess:'documental-and-math',reviewedRevision:state.patientRevision,reviewedAt:new Date().toISOString()};
  const items=[...state.rx.filter(x=>x.id!==editId),item];validatePrescriptionItems(items);state.rx=items;state.notesReviewedRevision=-1;closeDialog();navigate('prescricao');toast(p.result.mathOk===null?'Item incluído com posologia, instruções e fontes.':'Item incluído com posologia, instruções, fontes e cálculo reverso.');
 }catch(err){$('#regimen-error').innerHTML='<div class="error">'+esc(err.message)+'</div>';}};
}

function validatePrescriptionItems(items){validateTherapyCombination(items);for(const item of items){const r=regimens.find(r=>r.id===item.regimenId);if(!r)throw Error('Item manual em quarentena: falta vínculo documental canônico de medicamento e apresentação. Não emitir volume a partir de texto livre ou concentração declarada.');if(r){const check=regimenEligibility(r,patient());if(!check.eligible)throw Error(check.reasons.join(' '));if(r.requiresReason){const reason=String(item.rationale||'').trim();if(reason.length<20||reason===`Indicação informada: ${patient().diagnosis}. Esquema selecionado: ${r.title}. Fundamentação: ${r.conditions} ${r.offLabel}`.trim())throw Error('Registre justificativa individual do tratamento.');}const expected=prepareRegimen(r.id,{...patient(),regimenChecks:item.regimenChecks||[]},item.regimenPresentation||0,item.regimenDuration||'');if(r.catalogNew){if(JSON.stringify(item.calculation)!==JSON.stringify(expected.calculation)||item.name!==expected.name||item.route!==expected.route||item.presentation!==expected.presentation||item.duration!==expected.duration||item.instructions!==expected.instructions)throw Error('Reabra o esquema para recalcular para os dados atuais.');continue;}for(const k of ['basis','dose','unit','amount','concentrationUnit','volume','interval','maxDose','maxDay','maxKgDay','single','dropFactor'])if(String(item.form[k]??'')!==String(expected.form[k]??''))throw Error('Os parâmetros mudaram em relação ao esquema documentado. Selecione novamente o esquema ou use a prescrição individualizada com nova fonte.');if(item.route!==expected.route||expected.form.dropFactor&&Math.abs(Number(item.form.step)-expected.form.step)>1e-10)throw Error('Via ou graduação divergente da apresentação selecionada.');if(item.presentation!==expected.presentation||item.name!==expected.name||item.duration!==expected.duration)throw Error('Recarregue o esquema para a idade, apresentação e duração atuais.');}if(/cloperastina|levodropropizina|dropropizina/.test(norm(item.name))&&!coughAssessment(patient()).eligible)throw Error(coughAssessment(patient()).message);}}

function coverageHTML(){return `<div class="coverage-grid">${[[guidanceCoverage.total,'diagnósticos e temas pesquisados'],[guidanceCoverage.sourceReviewed,'rascunhos com fontes conferidas'],[guidanceCoverage.needsReview,'orientações sem perfil preenchido'],[regimens.length,'esquemas de dose estruturados']].map(([n,l])=>`<div class="coverage-tile"><strong>${n}</strong><span>${l}</span></div>`).join('')}</div><p class="inline-notes" style="margin:0 0 20px">${guidanceCoverage.revisedThisRelease?`${guidanceCoverage.revisedThisRelease} fichas ampliadas nesta revisão, com ${guidanceCoverage.contextOptions} opções de contexto e fontes por tema. `:''}Pesquisa documental assistida, com revisão médica individual antes de emitir. ${guidanceCoverage.originalTerms} termos originais preservados; variantes artificiais carregam cuidados do diagnóstico-base com identificação explícita, sem validar causas ou subtipos inexistentes. O inventário não representa todos os diagnósticos existentes na medicina.</p>`;}
function guidanceResults(){const list=filteredTopics(),size=30;state.topicPage=Math.min(state.topicPage,Math.max(0,Math.ceil(list.length/size)-1));$('#topic-results').innerHTML=`<div class="result-summary"><span>${list.length} diagnósticos e orientações encontrados</span><span>Conteúdo e procedência por registro</span></div><div class="panel guidance-diagnosis">${list.slice(state.topicPage*size,(state.topicPage+1)*size).map(row=>{const r=row.nativeRecords[0],imported=row.importedRecords[0];return `<div class="list-row"><div class="grow"><h3>${esc(row.name)}</h3><div class="chipline">${r?pill({home:'Domiciliar se elegível',specialist:'Seguimento especializado',urgent:'Avaliação urgente',hospital:'Hospitalar'}[r.setting]||'Individualizar',r.setting==='urgent'||r.setting==='hospital'?'amber':'gray'):pill(imported.category||'Catálogo PPS','gray')}${r?(r.status==='needs-review'?pill('Esclarecer escopo','amber'):pill('Fonte consultada','teal')):''}${r?.decisionSupport?.branchRequired?pill('Orientações por contexto','gray'):''}${imported?pill('PPS · conteúdo para consulta','gray'):''}</div>${imported?.populationLabel?`<p class="small-text">${esc(imported.populationLabel)}</p>`:''}</div><button class="button small outline" data-catalog-diagnosis="${esc(row.id)}">${r?'Ler orientações':'Consultar diagnóstico'}</button></div>`;}).join('')||'<div class="empty">Nenhum diagnóstico corresponde à busca. Tente sinônimo ou consulte o inventário original.</div>'}</div>${pager('topic',state.topicPage,list.length,size)}`;}
function ppsImportStatusHTML(){
 if(state.ppsStatus==='loading')return '<p class="inline-notes">Carregando os diagnósticos da Prescrição Pediátrica Segura. O conteúdo original da Integral permanece disponível.</p>';
 if(state.ppsStatus==='error')return '<div class="source-notice">Não foi possível carregar o catálogo PPS. O conteúdo original foi preservado; recarregue a página para tentar novamente.</div>';
 const counts=diagnosisCatalogStats(state.diagnosisCatalog);
 return `<p class="inline-notes">PPS v${esc(state.ppsSource.publishedVersion)}: ${counts.imported} registros importados; ${counts.reconciled} reunidos por nome completo correspondente, sem substituir o conteúdo da Integral. Os ${counts.native} registros originais permanecem disponíveis. A lista inclui contextos clínicos distintos e não representa validação universal de idade, diagnóstico ou tratamento.</p>`;
}
async function loadPpsDiagnoses(){
 try{const data=await getJSON('data/pps-diagnoses-index.json');if(data.schemaVersion!==1||!Array.isArray(data.entries)||data.source?.commit!=='941d6c61c9254b080b57520d9bcc4bc267caf6b6'||data.entries.length!==4878)throw Error('Catálogo PPS incompatível.');state.diagnosisCatalog=buildDiagnosisCatalog(guidanceRecords,data.entries);state.ppsSource=data.source;state.ppsStatus='ready';}
 catch{dataCache.delete('data/pps-diagnoses-index.json');state.ppsStatus='error';}
 if(state.route==='diagnosticos'&&state.topicMode==='guidance'){$('#pps-import-status').innerHTML=ppsImportStatusHTML();topicResults();}
}
let ppsContentPromise;
function loadPpsDiagnosticContent(){
 if(!ppsContentPromise)ppsContentPromise=getJSON('data/pps-diagnoses-content.json').then(data=>{const entries=new Map(data.entries?.map(entry=>[entry.value,entry])||[]);if(data.schemaVersion!==1||data.source?.commit!==state.ppsSource?.commit||entries.size!==4878)throw Error('Conteúdo PPS incompatível.');return entries;}).catch(error=>{dataCache.delete('data/pps-diagnoses-content.json');ppsContentPromise=null;throw error;});
 return ppsContentPromise;
}
function ppsDiagnosticHTML(record,content){
 if(!content||content.id!==record.id||content.name!==record.name)throw Error('Não foi possível conferir a identidade deste diagnóstico.');
 const eligibility=[...new Set([...(record.eligibilityRequirements||[]),...(content.eligibilityRequirements||[])])];
 return `<section class="guidance-block"><h3>${esc(record.name)}</h3><p class="small-text">Prescrição Pediátrica Segura · v${esc(state.ppsSource.publishedVersion)} · ${esc(record.value)}<br>${esc(record.category)}${content.category!==record.category?' · Classificação do conteúdo: '+esc(content.category):''}${record.origin?' · Origem do cadastro: '+esc(record.origin):''}${record.profile?' · Perfil na origem: '+esc(record.profile):''}</p><p>${record.contentTier==='catalog-review'?'Registro catalográfico para revisão; não equivale a protocolo completo ou tratamento validado.':'Registro com curadoria na origem PPS; esta cópia documental não importa nem valida o motor terapêutico.'}</p>${record.populationLabel?`<p><strong>População/contexto informado na origem:</strong> ${esc(record.populationLabel)}</p>`:''}${eligibility.length?`<ul>${eligibility.map(line=>`<li>${esc(line)}</li>`).join('')}</ul>`:''}${record.aliases?.length?`<p class="small-text">Nomes de busca preservados: ${record.aliases.map(esc).join('; ')}</p>`:''}${ppsDiagnosticFields.map(([key,label])=>`<section class="guidance-block"><h3>${label}</h3>${content[key]?.length?`<ul>${content[key].map(line=>`<li>${esc(line)}</li>`).join('')}</ul>`:'<p class="muted">Não informado neste campo da origem; nenhum conteúdo foi completado por inferência.</p>'}</section>`).join('')}<div class="guidance-sources"><h3>Procedência e referência informada na origem</h3><p><a href="${esc(safeURL(state.ppsSource.url)||'#')}" target="_blank" rel="noopener noreferrer">Prescrição Pediátrica Segura · versão ${esc(state.ppsSource.publishedVersion)} ↗</a></p>${content.source?`<p><a href="${esc(safeURL(content.source.url)||'#')}" target="_blank" rel="noopener noreferrer">${esc(content.source.label)} ↗</a> · ${esc(content.source.year||'')}</p>`:''}<p class="small-text">Os textos e as referências foram copiados da versão identificada, sem nova validação clínica das fontes. Os módulos de medicamentos e cálculos não foram migrados. Eventuais doses mencionadas na narrativa original são apenas documentais.</p></div></section>`;
}
async function showCatalogDiagnosis(id){
 const row=state.diagnosisCatalog.find(record=>record.id===id);if(!row)return;
 if(row.nativeRecords.length){showGuidance(row.nativeRecords[0].name);for(const extra of row.nativeRecords.slice(1))$('#dialog-content').insertAdjacentHTML('beforeend',`<details class="guidance-sources"><summary>Outro registro original preservado: ${esc(extra.name)}</summary><button class="button outline" data-choose-diagnosis="${esc(extra.name)}">Usar este registro original no atendimento</button>${guidanceDecisionHTML(extra)}${guidanceFields.map(([key,label])=>`<section class="guidance-block"><h3>${label}</h3><p>${esc(extra[key])}</p></section>`).join('')}<p>${esc(extra.reviewNotes||'')}</p>${(extra.sources||[]).map(source=>`<p><a href="${esc(safeURL(source.url)||'#')}" target="_blank" rel="noopener noreferrer">${esc(source.title)} ↗</a><br><small>Consulta: ${esc(source.accessed||'')}</small></p>`).join('')}</details>`);}
 else openDialog(row.name,`<div class="source-notice">${esc(PPS_IMPORT_SCOPE)}</div>`,'PPS · DIAGNÓSTICO PARA CONSULTA');
 if(!row.importedRecords.length)return;
 const generation=modalGeneration;$('#dialog-content').insertAdjacentHTML('beforeend','<div id="pps-diagnostic-detail" aria-live="polite"><p>Carregando o conteúdo diagnóstico importado…</p></div>');
 try{const content=await loadPpsDiagnosticContent();if(generation!==modalGeneration||!$('#detail-dialog').open)return;$('#pps-diagnostic-detail').innerHTML=(row.nativeRecords.length?`<div class="source-notice">Conteúdo da Integral acima preservado. ${esc(PPS_IMPORT_SCOPE)}</div>`:'')+row.importedRecords.map(record=>ppsDiagnosticHTML(record,content.get(record.value))).join('');}
 catch(error){if(generation===modalGeneration&&$('#detail-dialog').open)$('#pps-diagnostic-detail').innerHTML=`<div class="error">${esc(error.message)} Feche e reabra o diagnóstico para tentar novamente.</div>`;}
}
function showGuidance(name){const r=findGuidanceProfile(name);if(!r)return;openDialog(r.name,`<div class="source-notice">${esc(r.reviewNotes)}<p>Texto de apoio para revisão individual; não avalia elegibilidade para alta.</p></div><div class="button-row"><button class="button" data-choose-diagnosis="${esc(r.name)}">Usar neste atendimento</button><button class="button outline" data-search-term="${esc(r.name)}">Pesquisar no acervo</button></div>${guidanceDecisionHTML(r)}${guidanceFields.map(([k,l])=>`<section class="guidance-block"><h3>${l}</h3><p>${esc(r[k])}</p></section>`).join('')}<div class="guidance-sources"><h3>Fontes consultadas</h3>${r.sources.map(x=>`<p><a href="${esc(safeURL(x.url)||'#')}" target="_blank" rel="noopener noreferrer">${esc(x.title)} ↗</a><br><small>Consulta: ${esc(x.accessed)}</small></p>`).join('')}</div>`,'ORIENTAÇÕES · DIAGNÓSTICO E RETORNO');}

function shareRegimen(id){try{assertConfirmedHistory(patient());const index=Number($('#regimen-presentation').value),duration=$('#regimen-duration')?.value||'',r=prepareRegimen(id,patient(),index,duration),g=currentGuidance();validateGuidance(g);protocolDialog({diagnosis:patient().diagnosis,medicationId:r.medicationId,name:r.name,presentation:r.presentation,minMonths:r.minExclusive?r.minMonths+1:r.minMonths,maxMonths:Math.min(r.maxMonths,215.999),duration:r.duration,reference:r.reference,conditions:r.conditions,contraindications:r.contraindications,instructions:r.instructions,guidance:g,form:r.form,regimenId:id,regimenPresentation:index,regimenDuration:duration,therapyVersion:THERAPY_VERSION});}catch(e){toast(e.message);}}
